import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "Improved Right-Clicks", description = "Customize right-click menus with misclick protection, loot icons and persistent observed account badges.", tags = {
		"menu", "bank", "inventory", "misclick", "examine", "color" })
public class ImprovedMenusPlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ImprovedMenusConfig config;
	@Inject
	private EventBus eventBus;
	@Inject
	private ButtonGuard buttons;
	@Inject
	private MenuEngine engine;
	@Inject
	private ProfileStore store;
	@Inject
	private RenameNotice renameNotice;
	@Inject
	private ClientToolbar toolbar;
	@Inject
	private OverlayManager overlays;
	@Inject
	private MenuPresentation presentation;
	@Inject
	private MenuThemeRenderer menuTheme;
	@Inject
	private MenuStyle menuStyle;
	@Inject
	private OptionCountOverlay optionCounts;
	@Inject
	private ItemIcons itemIcons;
	@Inject
	private LootFiltersCompatibility lootCompatibility;
	@Inject
	private LootFiltersMenuPresentation lootMenu;
	@Inject
	private PlayerMenuBadges playerBadges;
	@Inject
	private AccountBadgeStore accountBadgeStore;
	@Inject
	private ReleaseNotesNotice releaseNotes;
	private ImprovedMenusPanel panel;
	private NavigationButton navigation;
	private volatile boolean active;
	private long lootRevision;

	@Provides
	ImprovedMenusConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(ImprovedMenusConfig.class);
	}

	@Override
	protected void startUp()
	{
		active = true;
		accountBadgeStore.start(playerBadges.accountBadges(), this::getPluginDirectory);
		presentation.setItemIcons(itemIcons);
		if (itemIcons.filters != null)
		{
			itemIcons.filters.reload();
		}
		renameNotice.startUp();
		releaseNotes.startUp();
		clientThread.invokeLater(() ->
		{
			if (active)
			{
				engine.reload();
				lootCompatibility.refresh();
				playerBadges.start();
				requestMenuStyle();
			}
		});
		buttons.startUp();
		eventBus.register(buttons);
		eventBus.register(menuTheme);
		overlays.add(optionCounts);
		overlays.add(playerBadges);
		presentation.start();
		SwingUtilities.invokeLater(this::updateSidePanel);
	}

	@Override
	protected void shutDown()
	{
		active = false;
		menuStyle.clear();
		accountBadgeStore.stop();
		eventBus.unregister(menuTheme);
		renameNotice.shutDown();
		releaseNotes.shutDown();
		eventBus.unregister(buttons);
		buttons.shutDown();
		overlays.remove(optionCounts);
		overlays.remove(playerBadges);
		clientThread.invoke(() ->
		{
			playerBadges.shutdown();
			presentation.stop();
			lootMenu.stop();
			lootCompatibility.reset();
			engine.clear();
		});
		store.clearHistory();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.stop();
				panel = null;
			}
			if (navigation != null)
			{
				toolbar.removeNavigation(navigation);
				navigation = null;
			}
		});
	}

	@Subscribe
	public void onClientShutdown(net.runelite.client.events.ClientShutdown event)
	{
		event.waitFor(accountBadgeStore.flush());
	}

	@Subscribe(priority = 100)
	public void onChatMessage(ChatMessage event)
	{
		if (active && client.getGameState() == GameState.LOGGED_IN)
			playerBadges.observeAccountBadge(event);
	}

	@Subscribe(priority = -0.5f)
	public void onPostMenuSort(PostMenuSort event)
	{
		if (!client.isMenuOpen())
		{
			engine.apply(client.getMenu());
		}
	}

	@Subscribe(priority = -1)
	public void onClientTick(ClientTick event)
	{
		if (!active || client.getGameState() != GameState.LOGGED_IN)
			return;
		if (!client.isMenuOpen())
			engine.applyTargetProtections(client.getMenu());
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!active)
			return;
		lootCompatibility.refresh();
		long revision = lootCompatibility.revision();
		if (revision != lootRevision)
		{
			lootRevision = revision;
			if (client.isMenuOpen())
				decorateMenu();
		}
	}

	@Subscribe(priority = -2)
	public void onMenuOpened(MenuOpened event)
	{
		playerBadges.clear();
		presentation.stop();
		lootMenu.stop();
		engine.applyOpened(client.getMenu());

		engine.groupOpened(client.getMenu());
		decorateMenu();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ImprovedMenusConfig.GROUP.equals(event.getGroup()))
		{
			if (itemIcons.filters != null
					&& (event.getKey().equals(FilterIcons.KEY) || event.getKey().equals(FilterIcons.BACKUP)))
			{
				itemIcons.filters.reload();
			}
			clientThread.invokeLater(() ->
			{
				if (active)
				{
					playerBadges.clear();
					presentation.stop();
					lootMenu.stop();
					lootCompatibility.reset();
					lootCompatibility.refresh();
					engine.reload();
					if (client.isMenuOpen())
						decorateMenu();
				}
			});
			if (event.getKey().equals("hideSidePanel"))
			{
				SwingUtilities.invokeLater(this::updateSidePanel);
			}
		}
		else if ("loot-filters".equals(event.getGroup()) || "improvedlooting".equals(event.getGroup()))
			refreshLootFilter();
	}

	@Subscribe
	public void onProfileChanged(net.runelite.client.events.ProfileChanged event)
	{
		menuStyle.clear();
		clientThread.invokeLater(() ->
		{
			if (active)
			{
				playerBadges.clear();
				releaseNotes.showIfLoggedIn();
				requestMenuStyle();
			}
		});
		refreshLootFilter();
		if (itemIcons.filters != null)
		{
			itemIcons.filters.reload();
		}
	}

	@Subscribe
	public void onPluginChanged(net.runelite.client.events.PluginChanged event)
	{
		if ("Right Click Styler".equals(event.getPlugin().getName()))
		{
			menuStyle.clear();
			clientThread.invokeLater(() ->
			{
				if (active)
					requestMenuStyle();
			});
		}
		if ("Loot Filters".equals(event.getPlugin().getName())
				|| "Loot Filters TEST".equals(event.getPlugin().getName())
				|| "Improved Looting".equals(event.getPlugin().getName())
				|| "Improved Looting TEST".equals(event.getPlugin().getName()))
			refreshLootFilter();
	}

	@Subscribe
	public void onPluginMessage(net.runelite.client.events.PluginMessage event)
	{
		if (active)
			menuStyle.accept(event);
		if (("loot-filters".equals(event.getNamespace()) || "improved-looting".equals(event.getNamespace()))
				&& "filter-reloaded".equals(event.getName()))
			refreshLootFilter();
	}

	private void requestMenuStyle()
	{
		eventBus.post(new net.runelite.client.events.PluginMessage(MenuStyle.NAMESPACE, "style-request"));
	}

	private void refreshLootFilter()
	{
		clientThread.invokeLater(() ->
		{
			if (!active)
				return;
			playerBadges.clear();
			presentation.stop();
			lootMenu.stop();
			lootCompatibility.reset();
			lootCompatibility.refresh();
			if (client.isMenuOpen())
				decorateMenu();
		});
	}

	private void decorateMenu()
	{

		playerBadges.clear();
		presentation.stop();
		lootMenu.stop();
		lootCompatibility.beginMenu();
		try
		{
			lootMenu.apply(client.getMenu());
			presentation.decorate(client.getMenu());
			playerBadges.decorate(client.getMenu());
		}
		finally
		{
			lootCompatibility.endMenu();
		}
	}

	@Subscribe(priority = 1)
	public void onBeforeMenuRender(BeforeMenuRender event)
	{
		if (active && client.isMenuOpen())
		{
			presentation.refreshIcons();
			engine.highlightHovered(client.getMenu());
		}
	}

	private void updateSidePanel()
	{
		if (!active || config.hideSidePanel())
		{
			if (navigation != null)
			{
				toolbar.removeNavigation(navigation);
				navigation = null;
			}
			if (panel != null)
			{
				panel.stop();
				panel = null;
			}
		}
		else if (navigation == null)
		{
			panel = new ImprovedMenusPanel(store, engine, this::openSettings, lootCompatibility::status);
			navigation = NavigationButton.builder().tooltip("Improved Right-Clicks").icon(icon()).priority(6)
					.panel(panel).build();
			toolbar.addNavigation(navigation);
		}
	}

	private void openSettings()
	{
		net.runelite.client.ui.overlay.Overlay target = new net.runelite.client.ui.overlay.Overlay(this)
		{
			@Override
			public java.awt.Dimension render(Graphics2D graphics)
			{
				return null;
			}
		};
		eventBus.post(new net.runelite.client.events.OverlayMenuClicked(
				new net.runelite.client.ui.overlay.OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG,
						net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE, "Improved Right-Clicks"),
				target));
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			playerBadges.clear();
			presentation.stop();
			lootMenu.stop();
			lootCompatibility.reset();
			buttons.reset();
			engine.clear();
		}
		else
		{
			renameNotice.showIfLoggedIn();
			releaseNotes.showIfLoggedIn();
		}
	}

	@Subscribe
	public void onFocusChanged(FocusChanged event)
	{
		if (!event.isFocused())
		{
			clientThread.invoke(buttons::reset);
		}
	}


	private static BufferedImage icon()
	{
		return net.runelite.client.util.ImageUtil.loadImageResource(ImprovedMenusPlugin.class, "sidebar-icon.png");
	}
}

package com.improvedmenus;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.IndexedSprite;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.util.AsyncBufferedImage;

final class InlineMenuIcons
{
	private static final int MAX_ICONS = 1000;
	private final Client client;
	private final ChatIconManager icons;
	private final List<Slot> slots = new ArrayList<>();
	private int used;

	InlineMenuIcons(Client client, ChatIconManager icons)
	{
		this.client = client;
		this.icons = icons;
	}

	void clear()
	{
		for (int i = 0; i < used; i++)
			slots.get(i).supplier = null;
		used = 0;
	}

	String add(Supplier<BufferedImage> supplier)
	{
		if (used == MAX_ICONS)
			return "";
		if (used == slots.size())
		{
			int id = icons.reserveChatIcon();
			icons.updateChatIcon(id, new BufferedImage(17, 15, BufferedImage.TYPE_INT_ARGB));
			slots.add(new Slot(id));
		}
		Slot slot = slots.get(used++);
		slot.supplier = supplier;
		int index = icons.chatIconIndex(slot.id);
		return index < 0 ? "" : "<img=" + index + ">";
	}

	void refresh()
	{
		for (int i = 0; i < used; i++)
		{
			Slot slot = slots.get(i);
			BufferedImage image = slot.supplier.get();
			if (image != slot.image)
			{
				slot.image = image;
				slot.dirty = true;
				if (image instanceof AsyncBufferedImage)
					((AsyncBufferedImage) image).onLoaded(() -> slot.dirty = true);
			}
			int index = icons.chatIconIndex(slot.id);
			IndexedSprite[] sprites = client.getModIcons();
			if (index < 0 || sprites == null || index >= sprites.length)
				continue;
			if (!slot.dirty && sprites[index] == slot.sprite)
				continue;
			slot.dirty = false;
			BufferedImage copy = new BufferedImage(17, 15, BufferedImage.TYPE_INT_ARGB);
			if (image != null)
			{
				Graphics2D graphics = copy.createGraphics();
				try
				{
					graphics.drawImage(image, 0, 0, 17, 15, null);
				}
				finally
				{
					graphics.dispose();
				}
			}
			icons.updateChatIcon(slot.id, copy);
			slot.sprite = client.getModIcons()[index];
		}
	}

	private static final class Slot
	{
		private final int id;
		private Supplier<BufferedImage> supplier;
		private BufferedImage image;
		private IndexedSprite sprite;
		private volatile boolean dirty = true;

		private Slot(int id)
		{
			this.id = id;
		}
	}
}

package com.improvedmenus;

import com.google.gson.Gson;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;

@Singleton
class ItemIcons
{
	static final String KEY = "itemIconAssignments", BACKUP = "itemIconBackup";

	enum Kind
	{
		HEART, STAR, DIAMOND, CURRENT_ITEM, ITEM, SPRITE, IMAGE
	}

	static final class Assignment
	{
		String image;
		String name;
		int itemId = -1;
		Kind kind;
		int iconId;
		int spriteIndex;

		String key()
		{
			return itemId >= 0 ? "id:" + itemId : "name:" + name.toLowerCase(Locale.ROOT);
		}

		@Override
		public String toString()
		{
			return (itemId >= 0 ? "Item #" + itemId : name) + " — " + kind
					+ (kind == Kind.ITEM || kind == Kind.SPRITE ? " #" + iconId : "");
		}
	}

	@Inject
	ConfigManager configs;
	@Inject
	Gson gson;
	@Inject
	ItemManager items;
	@Inject
	SpriteManager sprites;
	@Inject
	FilterIcons filters;
	private final Map<String, BufferedImage> imageCache = new LinkedHashMap<>();
	private final Map<Kind, BufferedImage> builtins = new EnumMap<>(Kind.class);
	private String cached;
	private List<Assignment> assignments = Collections.emptyList();

	synchronized List<Assignment> snapshot()
	{
		refreshAssignments();
		return new ArrayList<>(assignments);
	}

	private void refreshAssignments()
	{
		String raw = configs.getConfiguration(ImprovedMenusConfig.GROUP, KEY);
		if (!Objects.equals(raw, cached))
		{
			try
			{
				assignments = parse(raw == null ? "[]" : raw);
			}
			catch (IllegalArgumentException e)
			{
				assignments = Collections.emptyList();
			}
			cached = raw;
		}
	}

	List<Assignment> parse(String raw)
	{
		if (raw == null || raw.length() > 200000)
		{
			throw new IllegalArgumentException("Icon data is too large.");
		}
		try
		{
			Assignment[] data = gson.fromJson(raw, Assignment[].class);
			if (data == null || data.length > 500)
			{
				throw new IllegalArgumentException("Use at most 500 assignments.");
			}
			LinkedHashMap<String, Assignment> unique = new LinkedHashMap<>();
			for (Assignment a : data)
			{
				if (a == null || a.kind == null || a.itemId < -1 || a.itemId > 100000 || a.iconId < 0
						|| a.iconId > 100000 || a.spriteIndex < 0 || a.spriteIndex > 255
						|| (a.itemId < 0 && (a.name == null || a.name.trim().isEmpty() || a.name.length() > 120
								|| a.name.contains("<") || a.name.contains(">"))))
				{
					throw new IllegalArgumentException("Invalid icon assignment.");
				}
				if (a.kind == Kind.IMAGE)
				{
					IconImages.decode(a.image);
				}
				if (a.name != null)
				{
					a.name = a.name.trim();
				}
				unique.put(a.key(), a);
			}
			return new ArrayList<>(unique.values());
		}
		catch (com.google.gson.JsonParseException e)
		{
			throw new IllegalArgumentException("Invalid icon JSON.");
		}
	}

	String export()
	{
		return gson.toJson(snapshot());
	}

	void save(List<Assignment> next)
	{
		String json = gson.toJson(next);
		parse(json);
		configs.setConfiguration(ImprovedMenusConfig.GROUP, BACKUP, export());
		configs.setConfiguration(ImprovedMenusConfig.GROUP, KEY, json);
	}

	void undo()
	{
		String before = configs.getConfiguration(ImprovedMenusConfig.GROUP, BACKUP);
		if (before != null)
		{
			save(parse(before));
		}
	}

	synchronized Assignment find(int id)
	{
		refreshAssignments();
		List<Assignment> entries = assignments;
		for (Assignment a : entries)
		{
			if (a.itemId == id)
			{
				return a;
			}
		}
		if (entries.isEmpty())
		{
			return null;
		}
		String name = items.getItemComposition(id).getName();
		for (Assignment a : entries)
		{
			if (a.itemId < 0 && a.name.equalsIgnoreCase(name))
			{
				return a;
			}
		}
		return null;
	}

	BufferedImage image(Assignment a, int id)
	{
		if (a == null)
		{
			return null;
		}
		if (a.kind == Kind.CURRENT_ITEM || a.kind == Kind.ITEM)
		{
			return items.getImage(a.kind == Kind.CURRENT_ITEM ? id : a.iconId);
		}
		if (a.kind == Kind.IMAGE)
		{
			if (imageCache.size() > 256)
				imageCache.clear();
			return imageCache.computeIfAbsent(a.image, IconImages::decode);
		}
		if (a.kind == Kind.SPRITE)
		{
			try
			{
				return sprites.getSprite(a.iconId, a.spriteIndex);
			}
			catch (IndexOutOfBoundsException e)
			{
				return null;
			}
		}
		if (builtins.containsKey(a.kind))
		{
			return builtins.get(a.kind);
		}
		BufferedImage result = new BufferedImage(17, 15, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = result.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			if (a.kind == Kind.HEART)
			{
				g.setColor(new Color(255, 105, 110));
				g.fillOval(1, 1, 8, 8);
				g.fillOval(8, 1, 8, 8);
				g.fillPolygon(new int[] { 1, 16, 8 }, new int[] { 6, 6, 14 }, 3);
			}
			else if (a.kind == Kind.DIAMOND)
			{
				g.setColor(Color.CYAN);
				g.fillPolygon(new int[] { 8, 15, 8, 1 }, new int[] { 0, 7, 14, 7 }, 4);
			}
			else
			{
				g.setColor(new Color(255, 210, 60));
				Polygon star = new Polygon();
				for (int i = 0; i < 10; i++)
				{
					double angle = -Math.PI / 2 + i * Math.PI / 5;
					double radius = i % 2 == 0 ? 7 : 3;
					star.addPoint(8 + (int) (Math.cos(angle) * radius), 7 + (int) (Math.sin(angle) * radius));
				}
				g.fillPolygon(star);
			}
		}
		finally
		{
			g.dispose();
		}
		builtins.put(a.kind, result);
		return result;
	}
}

package com.improvedmenus;

import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.client.util.AsyncBufferedImage;

final class LootFilterImageCache
{
	private static final int LIMIT = 128;
	private final Map<Map<String, Object>, Entry> entries = new LinkedHashMap<>(16, .75f, true);
	private final Consumer<Runnable> clientThread;
	private long generation;
	private long revision;

	private static final class Entry
	{
		BufferedImage image;
		boolean complete;
		long requested = System.nanoTime();
	}

	LootFilterImageCache(Consumer<Runnable> clientThread)
	{
		this.clientThread = clientThread;
	}

	long revision()
	{
		return revision;
	}

	void clear()
	{
		generation++;
		revision++;
		entries.clear();
	}

	BufferedImage get(Map<String, Object> key, Supplier<?> provider)
	{
		Entry existing = entries.get(key);
		if (existing != null && (existing.image != null
				|| System.nanoTime() - existing.requested < (existing.complete ? 5_000_000_000L : 10_000_000_000L)))
		{
			return existing.image;
		}
		Entry entry = new Entry();
		entries.put(key, entry);
		if (entries.size() > LIMIT)
		{
			entries.remove(entries.keySet().iterator().next());
		}
		long version = generation;
		try
		{
			Object supplied = provider.get();
			if (supplied instanceof AsyncBufferedImage)
			{
				AsyncBufferedImage image = (AsyncBufferedImage) supplied;
				image.onLoaded(() -> clientThread.accept(() -> complete(key, entry, version, image)));
			}
			else if (supplied instanceof CompletableFuture)
			{
				((CompletableFuture<?>) supplied)
						.whenComplete((image, error) -> clientThread.accept(() -> complete(key, entry, version,
								error == null && image instanceof BufferedImage ? (BufferedImage) image : null)));
			}
			else
			{
				entry.complete = true;
			}
		}
		catch (RuntimeException error)
		{
			entry.complete = true;
		}
		return entry.image;
	}

	private void complete(Map<String, Object> key, Entry entry, long version, BufferedImage loaded)
	{
		if (version != generation || entries.get(key) != entry)
		{
			return;
		}
		entry.complete = true;
		if (loaded != null && loaded.getWidth() <= 1024 && loaded.getHeight() <= 1024)
		{
			if (loaded.getWidth() > 17 || loaded.getHeight() > 15)
			{
				entry.image = new BufferedImage(17, 15, BufferedImage.TYPE_INT_ARGB);
				var graphics = entry.image.createGraphics();
				try
				{
					graphics.drawImage(loaded, 0, 0, 17, 15, null);
				}
				finally
				{
					graphics.dispose();
				}
			}
			else
			{
				entry.image = new BufferedImage(loaded.getColorModel(), loaded.copyData(null),
						loaded.isAlphaPremultiplied(), null);
			}
		}
		revision++;
	}
}

package com.improvedmenus;

import com.improvedmenus.ImprovedMenusConfig.CustomIconProvider;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

@Singleton
class LootFiltersCompatibility
{
	private final Client client;
	private final ImprovedMenusConfig config;
	private final PluginManager plugins;
	private final EventBus events;
	private final LootFilterImageCache images;
	private boolean collecting, iconsEnabled;
	private CustomIconProvider menuProvider = CustomIconProvider.OFF, iconProvider = CustomIconProvider.OFF;
	private final Map<Tile, Map<Integer, Result>> menuResults = new IdentityHashMap<>();
	private final Map<Tile, Map<Integer, Result>> iconResults = new IdentityHashMap<>();
	private volatile String menuStatus = "Loot menu settings are off.", iconStatus = "Custom icon provider is Off.";

	@Inject
	LootFiltersCompatibility(Client client, ClientThread clientThread, ImprovedMenusConfig config,
			PluginManager plugins, EventBus events)
	{
		this.client = client;
		this.config = config;
		this.plugins = plugins;
		this.events = events;
		images = new LootFilterImageCache(clientThread::invokeLater);
	}

	static final class Result
	{
		final BufferedImage image;
		final boolean itemIcon, hidden, hideOverlay;
		final int menuSort;
		final Color menuColor;
		final Map<String, Object> icon;
		final Supplier<?> provider;

		Result(BufferedImage image, boolean itemIcon)
		{
			this(image, itemIcon, false, false, 0, null);
		}

		Result(BufferedImage image, boolean itemIcon, boolean hidden, boolean hideOverlay, int menuSort,
				Color menuColor)
		{
			this(image, itemIcon, hidden, hideOverlay, menuSort, menuColor, null, null);
		}

		Result(BufferedImage image, boolean itemIcon, boolean hidden, boolean hideOverlay, int menuSort,
				Color menuColor, Map<String, Object> icon, Supplier<?> provider)
		{
			this.image = image;
			this.itemIcon = itemIcon;
			this.hidden = hidden;
			this.hideOverlay = hideOverlay;
			this.menuSort = menuSort;
			this.menuColor = menuColor;
			this.icon = icon;
			this.provider = provider;
		}

		boolean hasIcon()
		{
			return !hidden && !hideOverlay && (image != null || icon != null && provider != null);
		}
	}

	String status()
	{
		return iconStatus + " " + menuStatus;
	}

	long revision()
	{
		return images.revision();
	}

	void refresh()
	{
		if (!client.isClientThread())
			return;
		CustomIconProvider nextMenu = CustomIconProvider.OFF;
		if (config.useLootFiltersInMenu())
		{
			if (available(CustomIconProvider.IMPROVED_LOOTING, false))
				nextMenu = CustomIconProvider.IMPROVED_LOOTING;
			else if (available(CustomIconProvider.LOOT_FILTERS, false))
				nextMenu = CustomIconProvider.LOOT_FILTERS;
		}
		CustomIconProvider nextIcon = config.customIconProvider();
		if (nextIcon == null)
			nextIcon = CustomIconProvider.OFF;
		boolean ready = available(nextIcon, true);
		if (nextIcon != iconProvider || ready != iconsEnabled)
		{
			images.clear();
			endMenu();
			iconProvider = nextIcon;
			iconsEnabled = ready;
			iconStatus = ready ? "Custom icons: " + iconProvider + "." : "Enable " + iconProvider + " for custom icons.";
		}
		if (nextMenu != menuProvider)
		{
			endMenu();
			menuProvider = nextMenu;
			menuStatus = "Loot menu settings: " + menuProvider + ".";
		}
		if (iconProvider == CustomIconProvider.OFF)
			iconStatus = "Custom icon provider is Off.";
		if (menuProvider == CustomIconProvider.OFF)
			menuStatus = config.useLootFiltersInMenu() ? "Enable a loot provider to use its menu settings."
					: "Loot menu settings are off.";
	}

	private boolean available(CustomIconProvider provider, boolean iconsOnly)
	{
		if (provider == CustomIconProvider.OFF)
			return false;
		for (Plugin plugin : plugins.getPlugins())
			if ((provider.label.equals(plugin.getName()) || (provider.label + " TEST").equals(plugin.getName()))
					&& plugins.isPluginActive(plugin))
			{
				if (provider == CustomIconProvider.LOOT_FILTERS)
					return true;
				Map<String, Object> capability = new HashMap<>();
				if (iconsOnly)
					capability.put("iconsOnly", true);
				events.post(new PluginMessage(provider.namespace, "provider-status-v1", capability));
				return Boolean.TRUE.equals(capability.get("enabled"));
			}
		return false;
	}

	void reset()
	{
		endMenu();
		images.clear();
		iconsEnabled = false;
		menuProvider = iconProvider = CustomIconProvider.OFF;
		iconStatus = "Custom icon provider is Off.";
		menuStatus = "Open a Take menu to check loot menu settings.";
	}

	void beginMenu()
	{
		refresh();
		menuResults.clear();
		iconResults.clear();
		collecting = true;
	}

	void endMenu()
	{
		menuResults.clear();
		iconResults.clear();
		collecting = false;
	}

	Result findIcon(MenuEntry entry)
	{
		Result result = find(entry, true);
		image(result);
		return result;
	}

	BufferedImage image(Result result)
	{
		if (result == null || !result.hasIcon() || !client.isClientThread())
			return null;
		if (result.image != null)
			return result.image;
		return images.get(result.icon, result.provider);
	}

	Result find(MenuEntry entry)
	{
		return find(entry, false);
	}

	private Result find(MenuEntry entry, boolean forIcons)
	{
		if (!(forIcons ? iconsEnabled : menuProvider != CustomIconProvider.OFF) || !client.isClientThread())
			return null;
		WorldView view = client.getWorldView(entry.getWorldViewId());
		if (view == null || view.getScene() == null)
			return null;
		Tile[][][] tiles = view.getScene().getTiles();
		int plane = view.getPlane(), x = entry.getParam0(), y = entry.getParam1();
		if (tiles == null || plane < 0 || plane >= tiles.length || tiles[plane] == null || x < 0
				|| x >= tiles[plane].length || tiles[plane][x] == null || y < 0 || y >= tiles[plane][x].length
				|| tiles[plane][x][y] == null)
			return null;
		if (!collecting)
			return request(view, x, y, plane, entry.getIdentifier(), forIcons);
		Map<Integer, Result> results = (forIcons ? iconResults : menuResults)
				.computeIfAbsent(tiles[plane][x][y], ignored -> new HashMap<>());
		if (!results.containsKey(entry.getIdentifier()))
			results.put(entry.getIdentifier(), request(view, x, y, plane, entry.getIdentifier(), forIcons));
		return results.get(entry.getIdentifier());
	}

	Result request(WorldView view, int x, int y, int plane, int itemId)
	{
		return request(view, x, y, plane, itemId, false);
	}

	private Result request(WorldView view, int x, int y, int plane, int itemId, boolean forIcons)
	{
		CustomIconProvider provider = forIcons ? iconProvider : menuProvider;
		if (provider == CustomIconProvider.OFF)
			return null;
		Map<String, Object> data = new HashMap<>();
		data.put("worldViewId", view.getId());
		data.put("x", view.getBaseX() + x);
		data.put("y", view.getBaseY() + y);
		data.put("z", plane);
		data.put("itemId", itemId);
		if (forIcons && provider == CustomIconProvider.IMPROVED_LOOTING)
			data.put("iconsOnly", true);
		events.post(new PluginMessage(provider.namespace, "resolved-display-request-v1", data));
		Result result = decode(data, itemId);
		String status = result != null
				? (forIcons ? "Custom icons: " : "Loot menu settings: ") + provider + "."
				: data.containsKey("status")
						? provider + " has no ready, unambiguous display settings for this pile."
						: "This " + provider
								+ " version does not provide resolved display settings. A compatible provider update is required.";
		if (forIcons)
			iconStatus = status;
		else
			menuStatus = status;
		return result;
	}

	static Result decode(Map<String, Object> data, int itemId)
	{
		if (!"ok".equals(data.get("status")) || !(data.get("display") instanceof Map))
			return null;
		Map<?, ?> display = (Map<?, ?>) data.get("display");
		if (!(display.get("hidden") instanceof Boolean) || !(display.get("hideOverlay") instanceof Boolean)
				|| !(display.get("menuSort") instanceof Integer)
				|| display.get("menuTextColor") != null && !(display.get("menuTextColor") instanceof Color))
			return null;
		Map<String, Object> descriptor = null;
		Supplier<?> provider = null;
		boolean same = false;
		if (display.get("icon") != null)
		{
			if (!(display.get("icon") instanceof Map))
				return null;
			Map<?, ?> icon = (Map<?, ?>) display.get("icon");
			Object type = icon.get("type");
			if (!(type instanceof String))
				return null;
			if (icon.get("getImage") instanceof Supplier)
				provider = (Supplier<?>) icon.get("getImage");
			descriptor = new HashMap<>();
			descriptor.put("type", type);
			for (String key : Arrays.asList("id", "index", "quantity", "height", "filename"))
			{
				Object value = icon.get(key);
				if (value != null && !(value instanceof Integer)
						&& !(key.equals("filename") && value instanceof String))
					return null;
				if (value != null)
					descriptor.put(key, value);
			}
			descriptor = Collections.unmodifiableMap(descriptor);
			same = ("item".equals(type) || "current-item".equals(type))
					&& Integer.valueOf(itemId).equals(icon.get("id"));
		}
		return new Result(null, same, (Boolean) display.get("hidden"), (Boolean) display.get("hideOverlay"),
				(Integer) display.get("menuSort"), (Color) display.get("menuTextColor"), descriptor, provider);
	}
}

package com.improvedmenus;

import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;

@Singleton
final class LootFiltersMenuPresentation
{
	@Inject
	private ImprovedMenusConfig config;
	@Inject
	private LootFiltersCompatibility compatibility;
	private final Map<MenuEntry, TargetEdit> colors = new IdentityHashMap<>();
	private Menu sortedMenu;
	private MenuEntry[] originalOrder, sortedOrder;
	private final Map<MenuEntry, Identity> identities = new IdentityHashMap<>();

	void apply(Menu menu)
	{
		stop();
		if (menu == null || !config.useLootFiltersInMenu())
			return;
		MenuEntry[] entries = menu.getMenuEntries();
		List<Integer> slots = new ArrayList<>();
		List<Ranked> rows = new ArrayList<>();
		for (int i = 0; i < entries.length; i++)
		{
			MenuEntry entry = entries[i];
			if (!isTake(entry) || entry.getSubMenu() != null)
				continue;
			LootFiltersCompatibility.Result display = compatibility.find(entry);
			if (display == null)
				continue;
			slots.add(i);
			rows.add(new Ranked(entry, display));

			if (config.lootFiltersMenuColors() && !display.hidden && display.menuColor != null)
			{
				String before = entry.getTarget();
				String after = String.format("<col=%06x>", display.menuColor.getRGB() & 0xffffff)
						+ before.replaceAll("</?col(?:=[^>]*)?>", "") + "</col>";
				if (!before.equals(after))
				{
					colors.put(entry, new TargetEdit(entry, before, after));
					entry.setTarget(after);
				}
			}
		}

		rows.sort((a, b) ->
		{
			int priority = Boolean.compare(b.deprioritized, a.deprioritized);
			return priority != 0 ? priority : Integer.compare(a.sort, b.sort);
		});
		MenuEntry[] ordered = entries.clone();
		for (int i = 0; i < slots.size(); i++)
			ordered[slots.get(i)] = rows.get(i).entry;
		if (!sameOrder(entries, ordered))
		{
			sortedMenu = menu;
			originalOrder = entries.clone();
			sortedOrder = ordered.clone();
			for (MenuEntry entry : entries)
				identities.put(entry, new Identity(entry));
			menu.setMenuEntries(ordered);
		}
	}

	void stop()
	{
		colors.forEach((entry, edit) ->
		{
			if (edit.identity.matches(entry) && edit.after.equals(entry.getTarget()))
				entry.setTarget(edit.before);
		});
		colors.clear();
		if (sortedMenu != null && sameOrder(sortedMenu.getMenuEntries(), sortedOrder)
				&& identities.entrySet().stream().allMatch(e -> e.getValue().matches(e.getKey())))
		{
			sortedMenu.setMenuEntries(originalOrder);
		}
		sortedMenu = null;
		originalOrder = null;
		sortedOrder = null;
		identities.clear();
	}

	static boolean isTake(MenuEntry entry)
	{
		MenuAction type = entry.getType();
		return (type == MenuAction.GROUND_ITEM_FIRST_OPTION || type == MenuAction.GROUND_ITEM_SECOND_OPTION
				|| type == MenuAction.GROUND_ITEM_THIRD_OPTION || type == MenuAction.GROUND_ITEM_FOURTH_OPTION
				|| type == MenuAction.GROUND_ITEM_FIFTH_OPTION) && "Take".equals(MenuRules.plain(entry.getOption()));
	}

	private static boolean sameOrder(MenuEntry[] a, MenuEntry[] b)
	{
		if (a.length != b.length)
			return false;
		for (int i = 0; i < a.length; i++)
			if (a[i] != b[i])
				return false;
		return true;
	}

	private static final class Ranked
	{
		final MenuEntry entry;
		final int sort;
		final boolean deprioritized;

		Ranked(MenuEntry entry, LootFiltersCompatibility.Result display)
		{
			this.entry = entry;
			sort = display.menuSort;
			deprioritized = entry.isDeprioritized();
		}
	}

	private static final class TargetEdit
	{
		final Identity identity;
		final String before, after;

		TargetEdit(MenuEntry entry, String before, String after)
		{
			identity = new Identity(entry);
			this.before = before;
			this.after = after;
		}
	}

	private static final class Identity
	{
		final MenuAction type;
		final int id, x, y, worldView;

		Identity(MenuEntry entry)
		{
			type = entry.getType();
			id = entry.getIdentifier();
			x = entry.getParam0();
			y = entry.getParam1();
			worldView = entry.getWorldViewId();
		}

		boolean matches(MenuEntry entry)
		{
			return type == entry.getType() && id == entry.getIdentifier() && x == entry.getParam0()
					&& y == entry.getParam1() && worldView == entry.getWorldViewId();
		}
	}
}

package com.improvedmenus;

import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.kit.KitType;
import net.runelite.api.widgets.Widget;

@Singleton
final class MenuEngine
{
	private static final Set<MenuAction> OBJECTS = EnumSet.of(MenuAction.GAME_OBJECT_FIRST_OPTION,
			MenuAction.GAME_OBJECT_SECOND_OPTION, MenuAction.GAME_OBJECT_THIRD_OPTION,
			MenuAction.GAME_OBJECT_FOURTH_OPTION, MenuAction.GAME_OBJECT_FIFTH_OPTION);
	private static final Set<MenuAction> ITEMS = EnumSet.of(MenuAction.CC_OP, MenuAction.CC_OP_LOW_PRIORITY,
			MenuAction.WIDGET_TARGET, MenuAction.WIDGET_TARGET_ON_WIDGET, MenuAction.GROUND_ITEM_FIRST_OPTION,
			MenuAction.GROUND_ITEM_SECOND_OPTION, MenuAction.GROUND_ITEM_THIRD_OPTION,
			MenuAction.GROUND_ITEM_FOURTH_OPTION, MenuAction.GROUND_ITEM_FIFTH_OPTION, MenuAction.EXAMINE_ITEM_GROUND);

	@Inject
	private Client client;
	@Inject
	private ImprovedMenusConfig config;
	@Inject
	private RevealState reveal;
	@Inject
	private TargetProtections targets;
	private List<MenuRules.Rule> itemRules = Collections.emptyList();
	private List<MenuRules.Rule> colors = Collections.emptyList();
	private List<MenuRules.Rule> exceptions = Collections.emptyList();
	private String validation = "";
	private volatile String diagnostics = "Hover an item or open a menu to preview changes.";
	private final IdentityHashMap<MenuEntry, ColorEdit> ownedColors = new IdentityHashMap<>();

	void reload()
	{
		restoreColors();

		List<String> errors = new ArrayList<>();
		try
		{
			itemRules = MenuRules.parseItems(config.itemRules());
		}
		catch (IllegalArgumentException e)
		{
			itemRules = Collections.emptyList();
			errors.add(e.getMessage());
		}
		try
		{
			colors = MenuRules.parseColors(config.colors());
		}
		catch (IllegalArgumentException e)
		{
			colors = Collections.emptyList();
			errors.add(e.getMessage());
		}
		try
		{
			exceptions = MenuRules.parseExceptions(config.exceptions());
		}
		catch (IllegalArgumentException e)
		{
			exceptions = Collections.emptyList();
			errors.add(e.getMessage());
		}
		validation = String.join("\n", errors);
	}

	String diagnostics()
	{
		return diagnostics;
	}

	void clear()
	{
		restoreColors();
		diagnostics = "Menu preview cleared.";
	}

	private void restoreColors()
	{
		ownedColors.forEach((entry, edit) ->
		{
			if (entry.getOption().equals(edit.after) && MenuRules.plain(entry.getTarget()).equals(edit.target)
					&& entry.getType() == edit.type && entry.getIdentifier() == edit.identifier)
			{
				entry.setOption(edit.before);
			}
		});
		ownedColors.clear();
	}

	void highlightHovered(Menu menu)
	{

		ownedColors.forEach((entry, edit) ->
		{
			if (edit.matches(entry))
			{
				entry.setOption(edit.colored);
				edit.after = edit.colored;
			}
		});
		if (!config.enableColors() || !config.yellowHover() || menu == null)
		{
			return;
		}
		MenuEntry hovered = hovered(menu);
		ColorEdit edit = ownedColors.get(hovered);
		if (edit != null && edit.matches(hovered))
		{

			edit.after = edit.colored.replaceAll("</?col(?:=[^>]*)?>", "");
			hovered.setOption(edit.after);
		}
	}

	private MenuEntry hovered(Menu menu)
	{
		if (menu.getMenuWidth() <= 0 || menu.getMenuHeight() <= 0)
		{
			return null;
		}
		MenuEntry[] entries = menu.getMenuEntries();

		Point mouse = client.getMouseCanvasPosition();
		int x = mouse.getX(), y = mouse.getY();
		if (x <= menu.getMenuX() || x >= menu.getMenuX() + menu.getMenuWidth() || y <= menu.getMenuY() + 18
				|| y >= menu.getMenuY() + menu.getMenuHeight())
		{
			return null;
		}
		int scroll = client.isMenuScrollable() ? client.getMenuScroll() : 0;
		for (int i = 0; i < entries.length; i++)
		{
			int baseline = menu.getMenuY() + 31 + (entries.length - 1 - i - scroll) * 15;
			if (y > baseline - 13 && y < baseline + 3)
			{
				return entries[i];
			}
		}
		return null;
	}

	void apply(Menu menu)
	{
		apply(menu, true);
	}

	void applyOpened(Menu menu)
	{
		apply(menu, false);
	}

	void groupOpened(Menu menu)
	{
		if (menu == null || reveal.isRevealed())
			return;
		if (config.groupGroundItems())
		{
			Map<MenuEntry, String> changed = GroundMenuGroups.collapse(menu);
			changed.forEach((entry, before) ->
			{
				ColorEdit edit = ownedColors.get(entry);
				if (edit != null && edit.after.equals(entry.getOption()) && edit.target.equals(MenuRules.plain(before)))
					edit.target = MenuRules.plain(entry.getTarget());
			});
			if (!changed.isEmpty())
				diagnostics += "\nGrouped duplicate ground-item actions in the opened menu.";
		}
		if (config.groundExamineLast())
			GroundMenuGroups.examineLast(menu);
	}

	private void apply(Menu menu, boolean capture)
	{
		if (menu == null || reveal.isRevealed())
		{
			diagnostics = "Reveal is held: filtering paused.";
			return;
		}
		StringBuilder report = new StringBuilder(validation);
		Context context = context();
		int before = menu.getMenuEntries().length;
		apply(menu, "", context, report, 0, capture && client.isKeyPressed(KeyCode.KC_SHIFT));
		if (!capture)
		{
			cleanOpenedMenu(menu, report, 0);
		}
		if (capture || before != menu.getMenuEntries().length)
		{
			String result = "Before: " + before + " entries. After: " + menu.getMenuEntries().length + " entries.\n"
					+ (report.length() == 0 ? "No changes to this menu." : report.toString());
			diagnostics = capture ? result : diagnostics + "\nOn opening:\n" + result;
		}
	}

	void applyTargetProtections(Menu menu)
	{
		if (menu == null || reveal.isRevealed() || !client.isWidgetSelected())
		{
			return;
		}
		MenuEntry[] entries = menu.getMenuEntries();
		List<MenuEntry> kept = new ArrayList<>(entries.length);
		StringBuilder report = new StringBuilder();
		for (MenuEntry entry : entries)
		{
			String reason = targets.reason(entry);
			if (reason == null)
			{
				kept.add(entry);
			}
			else
			{
				report.append("\nHide ").append(MenuRules.plain(entry.getOption())).append(" — ").append(reason);
			}
		}
		if (kept.size() != entries.length)
		{
			menu.setMenuEntries(kept.toArray(new MenuEntry[0]));
			diagnostics = "Before: " + entries.length + " entries. After: " + kept.size() + " entries.\n" + report;
		}
	}

	private void cleanOpenedMenu(Menu menu, StringBuilder report, int depth)
	{
		if (depth > 8)
		{
			return;
		}
		MenuEntry[] entries = menu.getMenuEntries();
		List<MenuEntry> kept = new ArrayList<>(entries.length);
		MenuEntry cancel = null;
		for (MenuEntry entry : entries)
		{
			if (entry.getSubMenu() != null)
			{
				cleanOpenedMenu(entry.getSubMenu(), report, depth + 1);
			}
			if (entry.getType() == MenuAction.CANCEL)
			{
				cancel = entry;
			}
			boolean hide = entry.getType() == MenuAction.CANCEL && config.hideCancel()
					|| entry.getType() == MenuAction.WALK && config.hideWalkHere()
					|| entry.getType() == MenuAction.SET_HEADING && config.hideSetHeading();
			if (!hide)
			{
				kept.add(entry);
			}
			else if (report.length() < 12000)
			{
				report.append("\nHide ").append(MenuRules.plain(entry.getOption()))
						.append(" — right-click menu cleanup");
			}
		}

		if (kept.isEmpty() && cancel != null)
		{
			kept.add(cancel);
			report.append("\nKeep Cancel — empty-menu fallback");
		}
		if (kept.size() != entries.length)
		{
			menu.setMenuEntries(kept.toArray(new MenuEntry[0]));
		}
	}

	private void apply(Menu menu, String inheritedTarget, Context context, StringBuilder report, int depth,
			boolean preserveSwapAnchors)
	{
		if (depth > 8)
		{
			return;
		}
		MenuEntry[] entries = menu.getMenuEntries();
		List<MenuEntry> kept = new ArrayList<>(entries.length);
		for (MenuEntry entry : entries)
		{

			if (preserveSwapAnchors && isSwapAnchor(entry))
			{
				ColorEdit edit = ownedColors.remove(entry);
				if (edit != null && edit.matches(entry))
				{
					entry.setOption(edit.before);
				}
				kept.add(entry);
				continue;
			}
			String target = MenuRules.plain(entry.getTarget());
			if (target.isEmpty())
			{
				target = inheritedTarget;
			}
			String option = MenuRules.plain(entry.getOption());
			String reason = reason(entry, entries, target, option, context);
			if (reason != null)
			{
				if (report.length() < 12000)
				{
					report.append("\nHide ").append(option).append(" ").append(target).append(" — ").append(reason);
				}
				continue;
			}
			if (entry.getSubMenu() != null)
			{
				apply(entry.getSubMenu(), target, context, report, depth + 1, preserveSwapAnchors);
			}
			if (config.enableColors())
			{
				String color = color(target, option);
				if (color != null)
				{

					ColorEdit prior = ownedColors.get(entry);
					String before = prior != null && prior.after.equals(entry.getOption()) ? prior.before
							: entry.getOption();
					String after = "<col=" + color + ">" + entry.getOption().replaceAll("</?col(?:=[^>]*)?>", "")
							+ "</col>";
					if (ownedColors.size() > 1024)
					{
						ownedColors.clear();
					}
					ownedColors.put(entry, new ColorEdit(before, after, entry));
					entry.setOption(after);
					if (report.length() < 12000)
					{
						report.append("\nColor ").append(option).append(" ").append(target).append(" #").append(color);
					}
				}
			}
			kept.add(entry);
		}

		if (kept.size() != entries.length)
		{
			menu.setMenuEntries(kept.toArray(new MenuEntry[0]));
		}
	}

	private static boolean isSwapAnchor(MenuEntry entry)
	{
		MenuAction type = entry.getType();
		if (type == MenuAction.EXAMINE_OBJECT || type == MenuAction.EXAMINE_NPC)
		{
			return true;
		}
		int group = entry.getParam1() >>> 16;
		return (type == MenuAction.CC_OP || type == MenuAction.CC_OP_LOW_PRIORITY)
				&& (group == InterfaceID.INVENTORY || group == InterfaceID.WORNITEMS) && entry.getIdentifier() == 10
				&& MenuRules.plain(entry.getOption()).equals("Examine");
	}

	String color(String target, String option)
	{
		for (MenuRules.Rule rule : colors)
		{
			if (rule.matches(target, option))
			{
				return rule.color;
			}
		}
		return null;
	}

	boolean excepted(String target, boolean inventory, boolean bank, boolean ground)
	{
		for (MenuRules.Rule rule : exceptions)
		{
			if (rule.applies(inventory, bank, ground) && rule.matches(target, ""))
			{
				return true;
			}
		}
		return false;
	}

	String reason(MenuEntry entry, MenuEntry[] siblings, String target, String option, Context c)
	{
		MenuAction type = entry.getType();
		String targetReason = targets.reason(entry);
		if (targetReason != null)
		{
			return targetReason;
		}
		boolean item = isItem(entry);
		boolean inventory = item && inventoryGroup(entry);
		boolean ground = type == MenuAction.EXAMINE_ITEM_GROUND || type == MenuAction.GROUND_ITEM_FIRST_OPTION
				|| type == MenuAction.GROUND_ITEM_SECOND_OPTION || type == MenuAction.GROUND_ITEM_THIRD_OPTION
				|| type == MenuAction.GROUND_ITEM_FOURTH_OPTION || type == MenuAction.GROUND_ITEM_FIFTH_OPTION;
		if (excepted(target, inventory, c.bank, ground))
		{
			return null;
		}
		if (inventory && c.bank)
		{
			if (option.equalsIgnoreCase("Wield") && config.bankWield()
					|| option.equalsIgnoreCase("Wear") && config.bankWear()
					|| option.equalsIgnoreCase("Drink") && config.bankDrink()
					|| option.equalsIgnoreCase("Eat") && config.bankEat())
			{
				return "bank protection";
			}
		}
		if (inventory && config.potionEmpty() && option.equalsIgnoreCase("Empty") && target.matches(".*\\([1-9]\\)$"))
		{
			return "potion Empty protection";
		}
		if (item)
		{
			for (MenuRules.Rule rule : itemRules)
			{
				if (rule.applies(inventory, c.bank, ground) && rule.matches(target, option))
				{
					return "custom item rule (" + rule.context.name().toLowerCase(Locale.ROOT) + ")";
				}
			}
		}
		if (type == MenuAction.EXAMINE_ITEM_GROUND && config.examineGround())
		{
			return "ground Examine";
		}
		if (item && option.equalsIgnoreCase("Examine") && type != MenuAction.EXAMINE_ITEM_GROUND
				&& config.examineInventory())
		{
			return "item Examine";
		}
		if (type == MenuAction.EXAMINE_NPC && config.examineNpc()
				&& !(config.keepLoneNpc() && loneExamine(entry, siblings)))
		{
			return "NPC Examine";
		}
		if (type == MenuAction.EXAMINE_OBJECT && config.examineObject()
				&& !(config.keepLoneObject() && loneExamine(entry, siblings)))
		{
			return "object Examine";
		}

		if (type == MenuAction.GAME_OBJECT_FIRST_OPTION && c.toolsKnown)
		{
			if (config.chop() && !c.axe
					&& entry.getIdentifier() != net.runelite.api.gameval.ObjectID.TEMPLETREK_SWAMPTREE_SMALL_VINES
					&& (option.startsWith("Chop") && (target.contains("ree") || ToolCatalog.CHOP.contains(target))
							|| option.startsWith("Cut") && (target.contains("ree") || target.equals("Sulliuscep"))))
			{
				return "axe required";
			}
			if (config.mine() && !c.pick && option.equals("Mine") && !target.equalsIgnoreCase("Cave entrance"))
			{
				return "pickaxe required";
			}
		}
		if (OBJECTS.contains(type))
		{
			if (config.house() && c.house && !c.building && HomeCatalog.OPTIONS.contains(option))
			{
				return "house building mode off";
			}
			if (config.mahogany() && option.equals("Remove") && !c.house)
			{
				Integer broken = HomeCatalog.REPAIRS.get(entry.getIdentifier());
				if (broken != null)
				{
					ObjectComposition object = client.getObjectDefinition(entry.getIdentifier());
					ObjectComposition active = object != null && object.getImpostorIds() != null ? object.getImpostor()
							: null;
					if (active != null && active.getId() != broken)
					{
						return "furniture does not need replacement";
					}
				}
			}
		}
		return null;
	}

	static boolean isItem(MenuEntry entry)
	{
		if (!ITEMS.contains(entry.getType()))
		{
			return false;
		}
		switch (entry.getType())
		{
			case EXAMINE_ITEM_GROUND:
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
				return true;
			default:
				return entry.getItemId() >= 0;
		}
	}

	static boolean inventoryGroup(MenuEntry entry)
	{
		int group = entry.getParam1() >>> 16;
		return group == InterfaceID.INVENTORY || group == InterfaceID.BANKSIDE;
	}

	private static boolean loneExamine(MenuEntry entry, MenuEntry[] entries)
	{
		for (MenuEntry other : entries)
		{
			if (other != entry && other.getIdentifier() == entry.getIdentifier()
					&& other.getParam0() == entry.getParam0() && other.getParam1() == entry.getParam1()
					&& MenuRules.plain(other.getTarget()).equals(MenuRules.plain(entry.getTarget()))
					&& other.getType() != MenuAction.CANCEL && other.getType() != MenuAction.WALK
					&& !MenuRules.plain(other.getOption()).equalsIgnoreCase("Examine"))
			{
				return false;
			}
		}
		return true;
	}

	private Context context()
	{
		Context c = new Context();
		Widget bank = client.getWidget(InterfaceID.BANKMAIN, 0);
		c.bank = bank != null && !bank.isHidden();
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		c.toolsKnown = inv != null && (worn != null || emptyEquipment());
		if (c.toolsKnown)
		{
			for (ItemContainer container : new ItemContainer[] { inv, worn })
			{
				if (container == null)
					continue;
				for (Item item : container.getItems())
				{
					if (item.getQuantity() > 0)
					{
						c.axe |= ToolCatalog.AXES.contains(item.getId());
						c.pick |= ToolCatalog.PICKS.contains(item.getId());
					}
				}
			}
		}
		if (client.getLocalPlayer() != null && client.getTopLevelWorldView() != null
				&& client.getTopLevelWorldView().isInstance())
		{
			WorldPoint point = WorldPoint.fromLocalInstance(client.getTopLevelWorldView().getScene(),
					client.getLocalPlayer().getLocalLocation(), client.getTopLevelWorldView().getPlane());
			c.house = point != null && HomeCatalog.REGIONS.contains(point.getRegionID());
		}
		c.building = c.house && client.getVarbitValue(VarbitID.POH_BUILDING_MODE) != 0;
		return c;
	}

	private boolean emptyEquipment()
	{
		Player player = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || player == null)
			return false;
		PlayerComposition appearance = player.getPlayerComposition();
		if (appearance == null || appearance.getEquipmentIds() == null)
			return false;
		int[] equipment = appearance.getEquipmentIds();
		if (equipment.length != KitType.JAW.getIndex() + 1)
			return false;
		for (int id : equipment)
			if (id < 0 || id >= PlayerComposition.ITEM_OFFSET)
				return false;
		return true;
	}

	static final class Context
	{
		boolean bank, toolsKnown, axe, pick, house, building;
	}

	private static final class ColorEdit
	{
		final String before, colored;
		String after, target;
		final MenuAction type;
		final int identifier;

		ColorEdit(String before, String after, MenuEntry entry)
		{
			this.before = before;
			this.after = after;
			this.colored = after;
			target = MenuRules.plain(entry.getTarget());
			type = entry.getType();
			identifier = entry.getIdentifier();
		}

		boolean matches(MenuEntry entry)
		{
			return entry.getOption().equals(after) && MenuRules.plain(entry.getTarget()).equals(target)
					&& entry.getType() == type && entry.getIdentifier() == identifier;
		}
	}
}

