package com.improvedmenus;

import java.awt.image.BufferedImage;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/** Icon row geometry adapted from Fiffers/ground-loot-icons; see bundled license. */
@Singleton
final class MenuPresentation
{
	private static final Set<MenuAction> GROUND = EnumSet.of(MenuAction.GROUND_ITEM_FIRST_OPTION,
			MenuAction.GROUND_ITEM_SECOND_OPTION, MenuAction.GROUND_ITEM_THIRD_OPTION,
			MenuAction.GROUND_ITEM_FOURTH_OPTION, MenuAction.GROUND_ITEM_FIFTH_OPTION);
	@Inject
	private Client client;
	@Inject
	private ImprovedMenusConfig config;
	@Inject
	private ItemManager items;
	@Inject
	private ChatIconManager icons;
	@Inject
	private TooltipManager tooltips;
	@Inject
	private LootFiltersCompatibility lootCompatibility;
	@Inject
	private net.runelite.client.config.RuneLiteConfig runeLiteConfig;
	@Inject
	private MenuStyle menuStyle;
	private InlineMenuIcons inlineIcons;
	private ItemIcons itemIcons;

	void setItemIcons(ItemIcons library)
	{
		itemIcons = library;
	}

	private final IdentityHashMap<MenuEntry, TargetEdit> ownedTargets = new IdentityHashMap<>();

	void start()
	{
		if (inlineIcons == null)
			inlineIcons = new InlineMenuIcons(client, icons);
	}

	void refreshIcons()
	{
		if (inlineIcons != null)
			inlineIcons.refresh();
	}

	void stop()
	{

		ownedTargets.forEach((entry, edit) ->
		{
			if (edit.matches(entry))
			{
				entry.setTarget(edit.original);
			}
		});
		ownedTargets.clear();
		if (inlineIcons != null)
			inlineIcons.clear();
	}

	void decorate(Menu menu)
	{
		stop();
		if (!config.groundIcons())
		{
			return;
		}

		if (menu == null)
		{
			return;
		}
		for (MenuEntry entry : menu.getMenuEntries())
		{
			if (GROUND.contains(entry.getType()) && "Take".equals(MenuRules.plain(entry.getOption())))
			{
				String original = entry.getTarget();
				ImprovedMenusConfig.GroundIconSource source = config.groundIconSource();
				ItemIcons.Assignment custom = source == ImprovedMenusConfig.GroundIconSource.NATIVE || source == null
						|| itemIcons == null ? null : itemIcons.find(entry.getIdentifier());
				LootFiltersCompatibility.Result linked = null;
				if (custom == null && source != null && source != ImprovedMenusConfig.GroundIconSource.NATIVE)
				{
					if (config.customIconProvider() != null
							&& config.customIconProvider() != ImprovedMenusConfig.CustomIconProvider.OFF)
					{
						linked = lootCompatibility.findIcon(entry);
						if (linked != null && !linked.hasIcon())
							linked = null;
					}
					else if (itemIcons != null && itemIcons.filters != null)
					{
						custom = itemIcons.filters.find(entry);
					}
				}
				if ((source == ImprovedMenusConfig.GroundIconSource.CUSTOM
						|| source == ImprovedMenusConfig.GroundIconSource.BOTH && config.bothRespectFilterVisibility())
						&& custom == null && linked == null)
				{
					continue;
				}
				boolean both = source == ImprovedMenusConfig.GroundIconSource.BOTH && custom != null
						&& custom.kind != ItemIcons.Kind.CURRENT_ITEM
						&& !(custom.kind == ItemIcons.Kind.ITEM && custom.iconId == entry.getIdentifier());
				both |= source == ImprovedMenusConfig.GroundIconSource.BOTH && linked != null && !linked.itemIcon;
				TargetEdit edit = new TargetEdit(entry, original);
				edit.nativeAllowed = source != ImprovedMenusConfig.GroundIconSource.CUSTOM
						&& !(source == ImprovedMenusConfig.GroundIconSource.BOTH
								&& config.bothRespectFilterVisibility());
				edit.custom = custom;
				edit.linked = linked;
				String decorated = inlineIcons.add(() -> firstIcon(edit));
				if (both)
					decorated += inlineIcons.add(() -> customIcon(edit) == null ? null
							: items.getImage(edit.identifier, Integer.MAX_VALUE, false));
				decorated += original;
				edit.decorated = decorated;
				if (decorated.equals(original))
				{
					continue;
				}
				ownedTargets.put(entry, edit);
				entry.setTarget(decorated);
			}
		}
	}

	void queueOptionCount()
	{
		if (!client.isMenuOpen() && config.optionCount())
		{
			int count = additionalCount(client.getMenu().getMenuEntries(), config.countExamine(),
					config.countOnWidgets(), config.countHidePlayers(), config.countHideWalkHere());
			if (count >= Math.max(1, config.minimumOptions()) && client.getMouseCanvasPosition().getX() >= 0)
			{
				java.awt.Color color = SettingsCatalog.colorOrDefault(config.optionCountColor(), java.awt.Color.WHITE);
				String text = String.format("<col=%06x>+%d options</col>", color.getRGB() & 0xffffff, count);
				ImprovedMenusConfig.CountAnchor anchor = config.countAnchor();
				boolean right = anchor == ImprovedMenusConfig.CountAnchor.BELOW_RIGHT
						|| anchor == ImprovedMenusConfig.CountAnchor.ABOVE_RIGHT;
				MenuStyle.Style style = config.followMenuStyle() ? menuStyle.current() : null;
				Tooltip tooltip = right || style != null
						? new Tooltip(new OptionCountTooltip(text, tooltips, client,
								runeLiteConfig.overlayBackgroundColor(), style, right)) : new Tooltip(text);
				if (anchor == ImprovedMenusConfig.CountAnchor.ABOVE_LEFT
						|| anchor == ImprovedMenusConfig.CountAnchor.ABOVE_RIGHT)
				{
					tooltips.addFront(tooltip);
				}
				else
				{
					tooltips.add(tooltip);
				}
			}
		}
	}

	static int additionalCount(MenuEntry[] entries)
	{
		return additionalCount(entries, true, true);
	}

	static int additionalCount(MenuEntry[] entries, boolean countExamine, boolean countOnWidgets)
	{
		return additionalCount(entries, countExamine, countOnWidgets, false, false);
	}

	static int additionalCount(MenuEntry[] entries, boolean countExamine, boolean countOnWidgets, boolean hidePlayers,
			boolean hideWalkHere)
	{
		MenuEntry primary = entries.length == 0 ? null : entries[entries.length - 1];

		MenuEntry worldPrimary = primary;
		if (hidePlayers)
		{
			worldPrimary = null;
			for (int i = entries.length - 1; i >= 0; i--)
			{
				if (!isPlayer(entries[i].getType()) && entries[i].getType() != MenuAction.CANCEL)
				{
					worldPrimary = entries[i];
					break;
				}
			}
		}
		boolean walking = hideWalkHere && worldPrimary != null && worldPrimary.getType() == MenuAction.WALK;
		int count = 0;
		boolean primaryCounted = false;
		for (MenuEntry entry : entries)
		{
			MenuAction type = entry.getType();
			if (hidePlayers && isPlayer(type))
			{
				continue;
			}
			if (walking && isNpcOrObject(type))
			{
				continue;
			}
			if (!countOnWidgets && entry.getWidget() != null)
			{
				continue;
			}
			if (!countExamine && (type == MenuAction.EXAMINE_NPC || type == MenuAction.EXAMINE_OBJECT
					|| type == MenuAction.EXAMINE_ITEM_GROUND
					|| MenuRules.plain(entry.getOption()).equalsIgnoreCase("Examine")))
			{
				continue;
			}
			if (type != MenuAction.CANCEL && type != MenuAction.WALK && type != MenuAction.WIDGET_CONTINUE
					&& type != MenuAction.RUNELITE && type != MenuAction.RUNELITE_OVERLAY
					&& type != MenuAction.RUNELITE_OVERLAY_CONFIG)
			{
				count++;
				if (entry == primary)
				{
					primaryCounted = true;
				}
			}
		}

		return Math.max(0, count - (!hidePlayers && !hideWalkHere || primaryCounted ? 1 : 0));
	}

	private static boolean isPlayer(MenuAction type)
	{
		return type == MenuAction.WIDGET_TARGET_ON_PLAYER || type == MenuAction.ITEM_USE_ON_PLAYER
				|| type == MenuAction.RUNELITE_PLAYER || type == MenuAction.PLAYER_FIRST_OPTION
				|| type == MenuAction.PLAYER_SECOND_OPTION || type == MenuAction.PLAYER_THIRD_OPTION
				|| type == MenuAction.PLAYER_FOURTH_OPTION || type == MenuAction.PLAYER_FIFTH_OPTION
				|| type == MenuAction.PLAYER_SIXTH_OPTION || type == MenuAction.PLAYER_SEVENTH_OPTION
				|| type == MenuAction.PLAYER_EIGHTH_OPTION;
	}

	private static boolean isNpcOrObject(MenuAction type)
	{
		return type == MenuAction.NPC_FIRST_OPTION || type == MenuAction.NPC_SECOND_OPTION
				|| type == MenuAction.NPC_THIRD_OPTION || type == MenuAction.NPC_FOURTH_OPTION
				|| type == MenuAction.NPC_FIFTH_OPTION || type == MenuAction.EXAMINE_NPC
				|| type == MenuAction.ITEM_USE_ON_NPC || type == MenuAction.WIDGET_TARGET_ON_NPC
				|| type == MenuAction.GAME_OBJECT_FIRST_OPTION || type == MenuAction.GAME_OBJECT_SECOND_OPTION
				|| type == MenuAction.GAME_OBJECT_THIRD_OPTION || type == MenuAction.GAME_OBJECT_FOURTH_OPTION
				|| type == MenuAction.GAME_OBJECT_FIFTH_OPTION || type == MenuAction.EXAMINE_OBJECT
				|| type == MenuAction.ITEM_USE_ON_GAME_OBJECT || type == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT;
	}

	private BufferedImage customIcon(TargetEdit edit)
	{
		return edit.linked != null
				? (edit.linked.image != null ? edit.linked.image : lootCompatibility.image(edit.linked))
				: edit.custom == null || itemIcons == null ? null : itemIcons.image(edit.custom, edit.identifier);
	}

	private BufferedImage firstIcon(TargetEdit edit)
	{
		BufferedImage custom = customIcon(edit);
		return custom != null ? custom : edit.nativeAllowed
				? items.getImage(edit.identifier, Integer.MAX_VALUE, false) : null;
	}

	private static final class TargetEdit
	{
		ItemIcons.Assignment custom;
		LootFiltersCompatibility.Result linked;
		boolean nativeAllowed;
		final String original;
		String decorated;
		final MenuAction type;
		final int identifier, param0, param1, worldView;

		TargetEdit(MenuEntry entry, String original)
		{
			this.original = original;
			type = entry.getType();
			identifier = entry.getIdentifier();
			param0 = entry.getParam0();
			param1 = entry.getParam1();
			worldView = entry.getWorldViewId();
		}

		boolean matches(MenuEntry entry)
		{
			return entry.getTarget().equals(decorated) && entry.getType() == type && entry.getIdentifier() == identifier
					&& entry.getParam0() == param0 && entry.getParam1() == param1
					&& entry.getWorldViewId() == worldView;
		}
	}
}

package com.improvedmenus;

import java.util.*;
import net.runelite.client.util.Text;

final class MenuRules
{
	static final int MAX_LENGTH = 16384;
	static final int MAX_RULES = 200;

	enum Context
	{
		ALL, INVENTORY, BANK, GROUND
	}

	static final class Rule
	{
		final Glob target;
		final Glob option;
		final String color;
		final boolean wildcard;
		final Context context;

		Rule(String target, String option, String color)
		{
			this(target, option, color, Context.ALL);
		}

		Rule(String target, String option, String color, Context context)
		{
			this.target = glob(target);
			this.option = glob(option);
			this.color = color;
			this.wildcard = target.contains("*") || option.contains("*");
			this.context = context;
		}

		boolean applies(boolean inventory, boolean bank, boolean ground)
		{
			switch (context)
			{
				case INVENTORY:
					return inventory;
				case BANK:
					return inventory && bank;
				case GROUND:
					return ground;
				default:
					return true;
			}
		}

		boolean matches(String target, String option)
		{
			return this.target.matches(plain(target)) && this.option.matches(plain(option));
		}
	}

	static String plain(String text)
	{
		return text == null ? "" : Text.removeTags(text).trim();
	}

	static Glob glob(String input)
	{
		if (input.length() > 256 || input.chars().filter(c -> c == '*').count() > 8)
		{
			throw new IllegalArgumentException("Use names of at most 256 characters and 8 wildcards");
		}
		return new Glob(input.trim());
	}

	static final class Glob
	{
		private final String pattern;

		Glob(String pattern)
		{
			this.pattern = pattern;
		}

		boolean matches(String value)
		{
			int p = 0, v = 0, star = -1, restart = 0;
			while (v < value.length())
			{
				if (p < pattern.length() && pattern.charAt(p) != '*'
						&& Character.toLowerCase(pattern.charAt(p)) == Character.toLowerCase(value.charAt(v)))
				{
					p++;
					v++;
				}
				else if (p < pattern.length() && pattern.charAt(p) == '*')
				{
					star = p++;
					restart = v;
				}
				else if (star >= 0)
				{
					p = star + 1;
					v = ++restart;
				}
				else
				{
					return false;
				}
			}
			while (p < pattern.length() && pattern.charAt(p) == '*')
			{
				p++;
			}
			return p == pattern.length();
		}
	}

	static List<Rule> parseItems(String input)
	{
		bounded(input);
		List<Rule> result = new ArrayList<>();
		int line = 0;
		for (String raw : input.split("\\R"))
		{
			line++;
			String s = raw.trim();
			if (s.isEmpty() || s.startsWith("#"))
			{
				continue;
			}
			Context context = context(s);
			s = stripContext(s);
			int comma = s.indexOf(',');
			if (comma < 1 || comma == s.length() - 1)
			{
				throw new IllegalArgumentException("Item rule line " + line + ": use action,item name");
			}
			result.add(new Rule(s.substring(comma + 1), s.substring(0, comma), null, context));
			if (result.size() > MAX_RULES)
			{
				throw new IllegalArgumentException("At most 200 rules are allowed");
			}
		}
		result.sort(Comparator.comparing(rule -> rule.wildcard));
		return Collections.unmodifiableList(result);
	}

	static List<Rule> parseColors(String input)
	{
		bounded(input);
		List<Rule> result = new ArrayList<>();
		for (String raw : input.split(";"))
		{
			if (raw.trim().isEmpty())
			{
				continue;
			}
			String[] p = raw.trim().split(":", -1);
			if (p.length != 3 || p[0].trim().isEmpty() || p[1].trim().isEmpty()
					|| !p[2].trim().matches("#[0-9a-fA-F]{6}"))
			{
				throw new IllegalArgumentException("Colors use target:action:#RRGGBB");
			}
			result.add(new Rule(p[0], p[1], p[2].trim().substring(1).toLowerCase(Locale.ROOT)));
			if (result.size() > MAX_RULES)
			{
				throw new IllegalArgumentException("At most 200 colors are allowed");
			}
		}

		result.sort(Comparator.comparing(rule -> rule.wildcard));
		return Collections.unmodifiableList(result);
	}

	static List<Rule> parseExceptions(String input)
	{
		bounded(input);
		List<Rule> result = new ArrayList<>();
		for (String raw : input.split("\\R"))
		{
			if (!raw.trim().isEmpty())
			{
				result.add(new Rule(stripContext(raw.trim()), "*", null, context(raw.trim())));
			}
			if (result.size() > MAX_RULES)
			{
				throw new IllegalArgumentException("At most 200 exceptions are allowed");
			}
		}
		return Collections.unmodifiableList(result);
	}

	private static Context context(String text)
	{
		if (!text.startsWith("["))
		{
			return Context.ALL;
		}
		int end = text.indexOf(']');
		if (end < 0)
		{
			throw new IllegalArgumentException("Use [inventory], [bank], [ground] or [all]");
		}
		try
		{
			return Context.valueOf(text.substring(1, end).trim().toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException e)
		{
			throw new IllegalArgumentException("Use [inventory], [bank], [ground] or [all]");
		}
	}

	private static String stripContext(String text)
	{
		if (!text.startsWith("["))
		{
			return text;
		}
		context(text);
		String result = text.substring(text.indexOf(']') + 1).trim();
		if (result.isEmpty())
		{
			throw new IllegalArgumentException("Add a rule after the context");
		}
		return result;
	}

	static void bounded(String input)
	{
		if (input == null || input.length() > MAX_LENGTH)
		{
			throw new IllegalArgumentException("Settings exceed the supported size");
		}
	}

	private MenuRules()
	{
	}
}

package com.improvedmenus;

import java.awt.Color;
import java.awt.Font;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.client.events.PluginMessage;

@Singleton
final class MenuStyle
{
	static final String NAMESPACE = "right-click-styler";
	private volatile Style current;

	void clear()
	{
		current = null;
	}

	Style current()
	{
		return current;
	}

	void accept(PluginMessage event)
	{
		if (!NAMESPACE.equals(event.getNamespace()) || !"style".equals(event.getName()))
			return;
		Map<String, Object> data = event.getData();
		if (Boolean.FALSE.equals(data.get("active")))
		{
			clear();
			return;
		}
		if (!Boolean.TRUE.equals(data.get("active")) || !Integer.valueOf(1).equals(data.get("version"))
				|| !(data.get("font") instanceof Font) || !(data.get("text") instanceof Color)
				|| !(data.get("background") instanceof Color) || !(data.get("border") instanceof Color)
				|| !(data.get("radius") instanceof Integer) || !(data.get("showBorder") instanceof Boolean)
				|| !(data.get("showShadow") instanceof Boolean) || !(data.get("textShadow") instanceof Boolean))
			return;
		Font font = (Font) data.get("font");
		int radius = (Integer) data.get("radius");
		if (font.getSize() < 1 || font.getSize() > 64 || radius < 0 || radius > 64)
			return;
		current = new Style(font, (Color) data.get("text"), (Color) data.get("background"),
				(Color) data.get("border"), radius, (Boolean) data.get("showBorder"),
				(Boolean) data.get("showShadow"), (Boolean) data.get("textShadow"));
	}

	static final class Style
	{
		final Font font;
		final Color text, background, border;
		final int radius;
		final boolean showBorder, showShadow, textShadow;

		Style(Font font, Color text, Color background, Color border, int radius, boolean showBorder,
				boolean showShadow, boolean textShadow)
		{
			this.font = font;
			this.text = text;
			this.background = background;
			this.border = border;
			this.radius = radius;
			this.showBorder = showBorder;
			this.showShadow = showShadow;
			this.textShadow = textShadow;
		}
	}
}

package com.improvedmenus;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;
import net.runelite.api.Rasterizer;
import net.runelite.api.events.BeforeMenuRender;
import net.runelite.client.eventbus.Subscribe;

@Singleton
final class MenuThemeRenderer
{
	static final int BACKGROUND = 0x372c1c, EDGE = 0x14100a, LIGHT = 0x9b8251, SHADE = 0x5a4529;
	private final Client client;
	private final ImprovedMenusConfig config;

	@Inject
	MenuThemeRenderer(Client client, ImprovedMenusConfig config)
	{
		this.client = client;
		this.config = config;
	}

	@Subscribe(priority = -100)
	public void onBeforeMenuRender(BeforeMenuRender event)
	{
		if (event.isConsumed() || config.menuTheme() != ImprovedMenusConfig.MenuTheme.OSRS || !client.isMenuOpen())
			return;
		Menu menu = client.getMenu();
		if (menu == null || menu.getMenuWidth() < 6 || menu.getMenuHeight() < 22)
			return;

		for (MenuEntry entry : menu.getMenuEntries())
			if (entry.getSubMenu() != null)
				return;
		Rasterizer rasterizer = client.getRasterizer();
		if (rasterizer == null)
			return;
		surface(rasterizer, menu.getMenuX(), menu.getMenuY(), menu.getMenuWidth(), menu.getMenuHeight());

		client.drawOriginalMenu(0);
		event.consume();
	}

	static void surface(Rasterizer r, int x, int y, int width, int height)
	{
		r.fillRectangle(x, y, width, height, EDGE);
		r.fillRectangle(x + 1, y + 1, width - 2, height - 2, LIGHT);
		r.fillRectangle(x + 1, y + height - 2, width - 2, 1, SHADE);
		r.fillRectangle(x + width - 2, y + 1, 1, height - 2, SHADE);
		r.fillRectangle(x + 2, y + 2, width - 4, height - 4, BACKGROUND);

		r.fillRectangle(x + 2, y + 2, width - 4, 15, EDGE);
		r.fillRectangle(x + 2, y + 17, width - 4, 1, SHADE);
	}
}

package com.improvedmenus;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.IconID;

final class ObservedAccountBadges
{
	static final int CAPACITY = 10000;
	private final Map<String, Observation> observed = new LinkedHashMap<>();
	private final Map<String, Observation> pending = new LinkedHashMap<>();

	static final class Observation
	{
		final Badge badge;
		final long seen;

		Observation(Badge badge, long seen)
		{
			this.badge = badge;
			this.seen = seen;
		}
	}

	enum Badge
	{
		JAGEX_MODERATOR(IconID.JAGEX_MODERATOR, "Jagex Moderator"),
		PLAYER_MODERATOR(IconID.PLAYER_MODERATOR, "Player Moderator"),
		HARDCORE_GROUP_IRONMAN(IconID.HARDCORE_GROUP_IRONMAN, "Hardcore Group Ironman"),
		UNRANKED_GROUP_IRONMAN(IconID.UNRANKED_GROUP_IRONMAN, "Unranked Group Ironman"),
		GROUP_IRONMAN(IconID.GROUP_IRONMAN, "Group Ironman"),
		HARDCORE_IRONMAN(IconID.HARDCORE_IRONMAN, "Hardcore Ironman"),
		ULTIMATE_IRONMAN(IconID.ULTIMATE_IRONMAN, "Ultimate Ironman"), IRONMAN(IconID.IRONMAN, "Ironman");

		final IconID icon;
		final String label;

		Badge(IconID icon, String label)
		{
			this.icon = icon;
			this.label = label;
		}
	}

	synchronized void observe(ChatMessageType type, String rawName)
	{
		if (type == null || !isIncomingPlayerChat(type))
			return;
		String key = key(rawName);
		if (key.isEmpty())
			return;
		Badge badge = fromName(rawName);
		Observation previous = observed.get(key);
		long now = System.currentTimeMillis();
		if (previous != null && previous.badge == badge && now - previous.seen < 60000)
			return;
		Observation next = new Observation(badge, previous == null ? now : Math.max(now, previous.seen + 1));
		observed.remove(key);
		observed.put(key, next);
		pending.remove(key);
		pending.put(key, next);
		trim(observed);
		trim(pending);
	}

	synchronized Badge find(String name)
	{
		Observation observation = observed.get(key(name));
		return observation == null ? null : observation.badge;
	}

	synchronized void clear()
	{
		observed.clear();
		pending.clear();
	}

	synchronized Map<String, Observation> pending()
	{
		return new LinkedHashMap<>(pending);
	}

	synchronized void saved(Map<String, Observation> records, Map<String, Observation> written)
	{
		merge(observed, records);
		written.forEach((name, entry) -> pending.remove(name, entry));
	}

	static void merge(Map<String, Observation> target, Map<String, Observation> incoming)
	{
		incoming.forEach((name, entry) ->
		{
			Observation old = target.get(name);
			if (old == null || entry.seen > old.seen || (entry.seen == old.seen && rank(entry.badge) < rank(old.badge)))
				target.put(name, entry);
		});
		trim(target);
	}

	private static int rank(Badge badge)
	{
		return badge == null ? -1 : badge.ordinal();
	}

	private static void trim(Map<String, Observation> records)
	{
		if (records.size() <= CAPACITY)
			return;
		java.util.List<String> names = new java.util.ArrayList<>(records.keySet());
		names.sort(java.util.Comparator.comparingLong(name -> records.get(name).seen));
		for (int i = 0; i < names.size() - CAPACITY; i++)
			records.remove(names.get(i));
	}

	static Badge fromName(String name)
	{
		if (name != null)
			for (Badge badge : Badge.values())
				if (name.contains(badge.icon.toString()))
					return badge;
		return null;
	}

	private static boolean isIncomingPlayerChat(ChatMessageType type)
	{
		switch (type)
		{
			case PUBLICCHAT:
			case MODCHAT:
			case AUTOTYPER:
			case MODAUTOTYPER:
			case PRIVATECHAT:
			case MODPRIVATECHAT:
			case FRIENDSCHAT:
			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
			case CLAN_GIM_CHAT:
				return true;
			default:
				return false;
		}
	}

	static String key(String name)
	{
		if (name == null)
			return "";
		String key = MenuRules.plain(name).replace('\u00a0', ' ').replace('_', ' ').trim().toLowerCase(Locale.ROOT);
		return key.matches("[a-z0-9 -]{1,12}") ? key : "";
	}
}

