package com.improvedmenus;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;

@Singleton
final class RevealState
{
	@Inject
	private Client client;
	@Inject
	private ImprovedMenusConfig config;

	boolean isRevealed()
	{
		if (config.revealKey() == ImprovedMenusConfig.RevealKey.NONE || client.getCanvas() == null
				|| !client.getCanvas().hasFocus())
		{
			return false;
		}
		switch (config.revealKey())
		{
			case CONTROL:
				return client.isKeyPressed(KeyCode.KC_CONTROL);
			case SHIFT:
				return client.isKeyPressed(KeyCode.KC_SHIFT);
			case ALT:
				return client.isKeyPressed(KeyCode.KC_ALT);
			default:
				return false;
		}
	}
}

package com.improvedmenus;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

final class SavedColourExport
{
	final String rules;
	final String retained;

	SavedColourExport(String saved)
	{
		List<MenuRules.Rule> parsed = MenuRules.parseColors(saved);
		Map<String, String> compatible = new LinkedHashMap<>();
		List<String> unsupported = new ArrayList<>();
		for (String raw : saved.split(";"))
		{
			if (raw.isBlank())
				continue;
			String[] parts = raw.trim().split(":");
			String target = parts[0].trim(), action = parts[1].trim();
			String key = action.toLowerCase(Locale.ROOT);
			if (!target.equals("*") || action.contains("*") || action.length() > 64
					|| action.contains("=") || action.contains("\n") || action.contains("\r")
					|| (!compatible.containsKey(key) && compatible.size() == 50)
					|| parsed.stream().anyMatch(rule -> rule.option.matches(action)
							&& !rule.color.equalsIgnoreCase(parts[2].trim().substring(1))))
			{
				unsupported.add(raw.trim());
				continue;
			}
			compatible.putIfAbsent(key, action + "=" + parts[2].trim());
		}
		rules = String.join("\n", compatible.values());
		retained = String.join("\n", unsupported);
	}
}

package com.improvedmenus;

import java.util.*;

final class SettingsCatalog
{
	static final class Setting
	{
		final String key, label, section, defaultValue;
		final String[] choices;

		Setting(String key, String label, String section, String defaultValue, String... choices)
		{
			this.key = key;
			this.label = label;
			this.section = section;
			this.defaultValue = defaultValue;
			this.choices = choices;
		}

		void validate(String value)
		{
			if (value == null)
			{
				throw new IllegalArgumentException("Missing value for " + label);
			}
			if (choices.length != 0 && !Arrays.asList(choices).contains(value))
			{
				throw new IllegalArgumentException("Invalid value for " + label);
			}
			if (key.equals("itemRules"))
			{
				MenuRules.parseItems(value);
			}
			else if (key.equals("colors"))
			{
				MenuRules.parseColors(value);
			}
			else if (key.equals("exceptions"))
			{
				MenuRules.parseExceptions(value);
			}
			else if (key.equals("defaultPickerColor") || key.equals("optionCountColor"))
			{
				if (!value.matches("#[0-9a-fA-F]{6}"))
				{
					throw new IllegalArgumentException("Use #RRGGBB for " + label);
				}
			}
			else if (key.equals("minimumOptions"))
			{
				try
				{
					int count = Integer.parseInt(value);
					if (count < 1 || count > 500)
					{
						throw new NumberFormatException();
					}
				}
				catch (NumberFormatException e)
				{
					throw new IllegalArgumentException("Use a whole number from 1 to 500 for " + label);
				}
			}
			else if (choices.length == 0)
			{
				MenuRules.bounded(value);
			}
		}
	}

