	@Test
	public void realEventBusPreservesObservationsAcrossSessionsProfilesAndSettingChanges() throws Exception
	{
		Fixture f = new Fixture();
		String original = f.entry.getTarget();
		ImprovedMenusPlugin plugin = new ImprovedMenusPlugin();
		field(plugin, "client", f.client);
		field(plugin, "config", f.config);
		field(plugin, "playerBadges", f.badges);
		field(plugin, "active", true);
		field(plugin, "menuStyle", new MenuStyle());
		field(plugin, "presentation", new MenuPresentation());
		field(plugin, "lootMenu", new LootFiltersMenuPresentation());
		field(plugin, "lootCompatibility", mock(LootFiltersCompatibility.class));
		field(plugin, "buttons", mock(ButtonGuard.class));
		ClientThread thread = mock(ClientThread.class);
		List<Runnable> queued = new ArrayList<>();
		MenuEngine engine = new MenuEngine();
		field(engine, "config", f.config);
		field(plugin, "engine", engine);
		when(f.config.itemRules()).thenReturn("");
		when(f.config.colors()).thenReturn("");
		when(f.config.exceptions()).thenReturn("");
		net.runelite.client.config.ConfigManager manager = mock(net.runelite.client.config.ConfigManager.class);
		net.runelite.client.chat.ChatMessageManager messages = mock(net.runelite.client.chat.ChatMessageManager.class);
		field(plugin, "releaseNotes", new ReleaseNotesNotice(f.client, thread, manager, messages));
		field(plugin, "renameNotice", new RenameNotice(f.client, thread, manager, messages));
		field(plugin, "itemIcons", mock(ItemIcons.class));
		doAnswer(call ->
		{
			queued.add(call.getArgument(0));
			return null;
		}).when(thread).invokeLater(any(Runnable.class));
		field(plugin, "clientThread", thread);
		EventBus bus = new EventBus(error ->
		{
			throw new AssertionError(error);
		});
		field(plugin, "eventBus", bus);
		bus.register(plugin);
		for (GameState state : new GameState[] { GameState.HOPPING, GameState.LOGIN_SCREEN, GameState.CONNECTION_LOST })
		{
			bus.post(f.chat("<img=2>Alice"));
			f.badges.decorate(f.menu);
			assertEquals("<img=2>" + original, f.entry.getTarget());
			GameStateChanged change = new GameStateChanged();
			change.setGameState(state);
			bus.post(change);
			f.badges.decorate(f.menu);
			assertEquals("<img=2>" + original, f.entry.getTarget());
		}
		bus.post(f.chat("<img=2>Alice"));
		GameStateChanged loading = new GameStateChanged();
		loading.setGameState(GameState.LOADING);
		bus.post(loading);
		f.badges.decorate(f.menu);
		assertEquals("<img=2>" + original, f.entry.getTarget());
		bus.post(new ProfileChanged());
		queued.forEach(Runnable::run);
		queued.clear();
		f.badges.decorate(f.menu);
		assertEquals("<img=2>" + original, f.entry.getTarget());
		bus.post(f.chat("<img=2>Alice"));
		when(f.config.playerAccountBadge()).thenReturn(false);
		ConfigChanged config = new ConfigChanged();
		config.setGroup(ImprovedMenusConfig.GROUP);
		config.setKey("playerAccountBadge");
		bus.post(config);
		queued.forEach(Runnable::run);
		queued.clear();
		when(f.config.playerAccountBadge()).thenReturn(true);
		f.badges.decorate(f.menu);
		assertEquals("<img=2>" + original, f.entry.getTarget());
		field(plugin, "active", false);
		bus.post(f.chat("<img=10>Alice"));
		f.badges.decorate(f.menu);
		assertEquals("<img=2>" + original, f.entry.getTarget());
		bus.unregister(plugin);
	}

	private static void field(Object object, String name, Object value) throws Exception
	{
		Field field = object.getClass().getDeclaredField(name);
		field.setAccessible(true);
		field.set(object, value);
	}
}

package com.improvedmenus;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import net.runelite.api.ChatMessageType;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class AccountBadgeStoreTest
{
	@Rule
	public TemporaryFolder temporary = new TemporaryFolder();

	private Filepath root()
	{
		return Filepath.Unchecked.getRooted(temporary.getRoot().toPath());
	}

	private AccountBadgeStore store(ObservedAccountBadges cache)
	{
		ScheduledExecutorService executor = mock(ScheduledExecutorService.class);
		doReturn(mock(ScheduledFuture.class)).when(executor).scheduleWithFixedDelay(any(Runnable.class), eq(0L), eq(5L),
				eq(TimeUnit.SECONDS));
		AccountBadgeStore store = new AccountBadgeStore(new Gson(), executor);
		store.start(cache, this::root);
		return store;
	}

	private void observe(ObservedAccountBadges cache, String name)
	{
		cache.observe(ChatMessageType.PUBLICCHAT, name);
	}

	private String file() throws IOException
	{
		return Files.readString(temporary.getRoot().toPath().resolve(AccountBadgeStore.FILE_NAME));
	}

	@Test
	public void allBadgesSurviveNewPluginAndClientInstances() throws Exception
	{
		ObservedAccountBadges first = new ObservedAccountBadges();
		int i = 0;
		for (ObservedAccountBadges.Badge badge : ObservedAccountBadges.Badge.values())
			observe(first, badge.icon + "Player" + i++);
		AccountBadgeStore writer = store(first);
		assertTrue(writer.synchronize());
		assertTrue(first.pending().isEmpty());
		ObservedAccountBadges fresh = new ObservedAccountBadges();
		assertTrue(store(fresh).synchronize());
		i = 0;
		for (ObservedAccountBadges.Badge badge : ObservedAccountBadges.Badge.values())
			assertSame(badge, fresh.find("PLAYER" + i++));
		assertTrue(file().contains("\"version\":1"));
		assertFalse(file().contains("<img="));
	}

	@Test
	public void simultaneousClientsMergeNamesAndKeepLatestCorrections() throws Exception
	{
		ObservedAccountBadges a = new ObservedAccountBadges(), b = new ObservedAccountBadges();
		AccountBadgeStore first = store(a), second = store(b);
		first.synchronize();
		second.synchronize();
		observe(a, "<img=10>Alice");
		first.synchronize();
		observe(b, "<img=3>Bob");
		second.synchronize();
		first.synchronize();
		assertSame(ObservedAccountBadges.Badge.ULTIMATE_IRONMAN, a.find("Bob"));
		assertSame(ObservedAccountBadges.Badge.HARDCORE_IRONMAN, b.find("Alice"));
		observe(b, "<img=2>Alice");
		second.synchronize();
		observe(a, "<img=41>Charlie");
		first.synchronize();
		assertSame(ObservedAccountBadges.Badge.IRONMAN, a.find("Alice"));
		observe(b, "Alice");
		second.synchronize();
		observe(a, "<img=42>Dan");
		first.synchronize();
		ObservedAccountBadges fresh = new ObservedAccountBadges();
		store(fresh).synchronize();
		assertNull(fresh.find("Alice"));
		assertSame(ObservedAccountBadges.Badge.ULTIMATE_IRONMAN, fresh.find("Bob"));
		assertSame(ObservedAccountBadges.Badge.GROUP_IRONMAN, fresh.find("Charlie"));
		assertSame(ObservedAccountBadges.Badge.HARDCORE_GROUP_IRONMAN, fresh.find("Dan"));
		assertTrue(file().contains("NONE"));
	}

	@Test
	public void chatBeforeInitialLoadWinsOverOlderDiskStatus() throws Exception
	{
		root().join(AccountBadgeStore.FILE_NAME)
				.write("{\"version\":1,\"accounts\":{\"alice\":{\"badge\":\"HARDCORE_IRONMAN\",\"seen\":100}}}");
		ObservedAccountBadges cache = new ObservedAccountBadges();
		observe(cache, "Alice");
		assertTrue(store(cache).synchronize());
		assertNull(cache.find("Alice"));
		ObservedAccountBadges fresh = new ObservedAccountBadges();
		store(fresh).synchronize();
		assertNull(fresh.find("Alice"));
	}

	@Test
	public void observationsMadeDuringWriteRemainPending()
	{
		ObservedAccountBadges cache = new ObservedAccountBadges();
		observe(cache, "<img=10>Alice");
		Map<String, ObservedAccountBadges.Observation> writing = cache.pending();
		observe(cache, "<img=2>Alice");
		cache.saved(writing, writing);
		assertSame(ObservedAccountBadges.Badge.IRONMAN, cache.find("Alice"));
		assertSame(ObservedAccountBadges.Badge.IRONMAN, cache.pending().get("alice").badge);
	}

	@Test
	public void corruptOrFutureFilesArePreservedAndMemoryCacheStillWorks() throws Exception
	{
		for (String contents : new String[] { "{bad json", "{\"version\":2,\"accounts\":{}}", "null" })
		{
			root().join(AccountBadgeStore.FILE_NAME).write(contents);
			ObservedAccountBadges cache = new ObservedAccountBadges();
			observe(cache, "<img=2>Alice");
			assertFalse(store(cache).synchronize());
			assertSame(ObservedAccountBadges.Badge.IRONMAN, cache.find("Alice"));
			assertFalse(cache.pending().isEmpty());
			assertEquals(contents, file());
		}
	}

	@Test
	public void invalidEntriesCannotInjectMenuMarkupOrUnsupportedBadges() throws Exception
	{
		root().join(AccountBadgeStore.FILE_NAME)
				.write("{\"version\":1,\"accounts\":{" + "\"<img=1>alice\":{\"badge\":\"IRONMAN\",\"seen\":100},"
						+ "\"bob\":{\"badge\":\"ARBITRARY\",\"seen\":100},"
						+ "\"charlie\":{\"badge\":\"IRONMAN\",\"seen\":-1},"
						+ "\"dan\":{\"badge\":\"IRONMAN\",\"seen\":1.5},"
						+ "\"eve\":{\"badge\":\"ULTIMATE_IRONMAN\",\"seen\":100}}}");
		ObservedAccountBadges cache = new ObservedAccountBadges();
		assertTrue(store(cache).synchronize());
		for (String name : new String[] { "Alice", "Bob", "Charlie", "Dan" })
			assertNull(cache.find(name));
		assertSame(ObservedAccountBadges.Badge.ULTIMATE_IRONMAN, cache.find("Eve"));
	}

	@Test
	public void oversizedFileIsRejectedWithoutOverwritingIt() throws Exception
	{
		byte[] bytes = new byte[AccountBadgeStore.MAX_BYTES + 1];
		root().join(AccountBadgeStore.FILE_NAME).write(bytes);
		ObservedAccountBadges cache = new ObservedAccountBadges();
		observe(cache, "<img=2>Alice");
		assertFalse(store(cache).synchronize());
		assertEquals(bytes.length, root().join(AccountBadgeStore.FILE_NAME).size());
		assertFalse(cache.pending().isEmpty());
	}

	@Test
	public void concurrentFileLockDefersWriteWithoutLosingPendingObservations() throws Exception
	{
		ObservedAccountBadges cache = new ObservedAccountBadges();
		observe(cache, "<img=2>Alice");
		AccountBadgeStore store = store(cache);
		try (FileChannel channel = root().join("account-badges.lock").openFileChannel(StandardOpenOption.CREATE,
				StandardOpenOption.WRITE); FileLock lock = channel.lock())
		{
			assertFalse(store.synchronize());
			assertFalse(cache.pending().isEmpty());
			assertFalse(root().join(AccountBadgeStore.FILE_NAME).exists());
		}
		assertTrue(store.synchronize());
		assertTrue(cache.pending().isEmpty());
	}

	@Test
	public void failedReplacementPreservesOldFileAndRetriesPendingUpdate() throws Exception
	{
		ObservedAccountBadges cache = new ObservedAccountBadges();
		observe(cache, "<img=2>Alice");
		store(cache).synchronize();
		String original = file();
		observe(cache, "<img=10>Alice");
		Filepath directory = spy(root());
		Filepath broken = spy(root().createTempFile("test-", ".tmp"));
		doReturn(broken).when(directory).createTempFile("account-badges-", ".tmp");
		doThrow(new IOException("simulated replacement failure")).when(broken).moveTo(any(Filepath.class),
				eq(StandardCopyOption.ATOMIC_MOVE), eq(StandardCopyOption.REPLACE_EXISTING));
		AccountBadgeStore failing = new AccountBadgeStore(new Gson(), mock(ScheduledExecutorService.class));
		failing.start(cache, () -> directory);
		assertFalse(failing.synchronize());
		assertEquals(original, file());
		assertFalse(cache.pending().isEmpty());
		assertFalse(broken.exists());
		assertTrue(store(cache).synchronize());
		assertTrue(file().contains("HARDCORE_IRONMAN"));
	}

	@Test
	public void shutdownEventWaitsForTheBackgroundSave() throws Exception
	{
		ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
		try
		{
			ObservedAccountBadges cache = new ObservedAccountBadges();
			AccountBadgeStore store = new AccountBadgeStore(new Gson(), executor);
			store.start(cache, this::root);
			observe(cache, "<img=10>Alice");
			ImprovedMenusPlugin plugin = new ImprovedMenusPlugin();
			java.lang.reflect.Field field = ImprovedMenusPlugin.class.getDeclaredField("accountBadgeStore");
			field.setAccessible(true);
			field.set(plugin, store);
			EventBus bus = new EventBus(error ->
			{
				throw new AssertionError(error);
			});
			bus.register(plugin);
			ClientShutdown event = new ClientShutdown();
			bus.post(event);
			assertEquals(1, event.getTasks().size());
			event.getTasks().peek().get(5, TimeUnit.SECONDS);
			assertTrue(file().contains("HARDCORE_IRONMAN"));
			store.stop().get(5, TimeUnit.SECONDS);
			bus.unregister(plugin);
		}
		finally
		{
			executor.shutdown();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
		}
	}

	@Test
	public void cacheMergesKeepOnlyMostRecentTenThousandPlayers()
	{
		Map<String, ObservedAccountBadges.Observation> first = new LinkedHashMap<>(), second = new LinkedHashMap<>();
		for (int i = 0; i < ObservedAccountBadges.CAPACITY; i++)
			first.put("player" + i, new ObservedAccountBadges.Observation(ObservedAccountBadges.Badge.IRONMAN, i + 1));
		second.put("newest", new ObservedAccountBadges.Observation(ObservedAccountBadges.Badge.IRONMAN, 20000));
		ObservedAccountBadges.merge(first, second);
		assertEquals(ObservedAccountBadges.CAPACITY, first.size());
		assertFalse(first.containsKey("player0"));
		assertTrue(first.containsKey("newest"));
	}

	@Test
	public void unchangedReadsCanRehydrateMemoryAndSameSizeExternalEditsAreDetected() throws Exception
	{
		ObservedAccountBadges cache = new ObservedAccountBadges();
		AccountBadgeStore first = store(cache);
		observe(cache, "<img=2>Alice");
		assertTrue(first.synchronize());
		cache.clear();
		assertTrue(first.synchronize());
		assertSame(ObservedAccountBadges.Badge.IRONMAN, cache.find("Alice"));
		java.nio.file.Path file = temporary.getRoot().toPath().resolve(AccountBadgeStore.FILE_NAME);
		java.nio.file.attribute.FileTime modified = Files.getLastModifiedTime(file);
		String edited = Files.readString(file).replace("alice", "carol");
		Files.writeString(file, edited);
		Files.setLastModifiedTime(file, modified);
		assertTrue(first.synchronize());
		assertSame(ObservedAccountBadges.Badge.IRONMAN, cache.find("Carol"));
		observe(cache, "<img=3>Bob");
		assertTrue(first.synchronize());
		ObservedAccountBadges other = new ObservedAccountBadges();
		assertTrue(store(other).synchronize());
		assertSame(ObservedAccountBadges.Badge.IRONMAN, other.find("Carol"));
		assertSame(ObservedAccountBadges.Badge.ULTIMATE_IRONMAN, other.find("Bob"));
	}
}

package com.improvedmenus;

import com.google.inject.*;
import java.awt.Canvas;
import java.awt.event.MouseEvent;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.input.MouseManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.callback.ClientThread;
import org.junit.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ButtonGuardTest
{
	private Client client;
	private ImprovedMenusConfig config;
	private MouseManager mouse;
	private ButtonGuard guard;
	private final AtomicReference<MouseListener> listener = new AtomicReference<>();

	@Before
	public void setup()
	{
		client = mock(Client.class);
		config = mock(ImprovedMenusConfig.class);
		mouse = mock(MouseManager.class);
		when(config.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.NONE);
		when(config.autoRetaliate()).thenReturn(ClickMode.NORMAL);
		when(config.xpDrops()).thenReturn(ClickMode.NORMAL);
		when(config.alwaysSetPlaceholders()).thenReturn(ClickMode.NORMAL);
		when(config.report()).thenReturn(ClickMode.NORMAL);
		doAnswer(i ->
		{
			listener.set(i.getArgument(0));
			return null;
		}).when(mouse).registerMouseListener(any(MouseListener.class));
		ClientThread thread = mock(ClientThread.class);
		doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(thread).invoke(any(Runnable.class));
		doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(thread).invokeLater(any(Runnable.class));
		guard = Guice.createInjector(new AbstractModule()
		{
			protected void configure()
			{
				bind(Client.class).toInstance(client);
				bind(ImprovedMenusConfig.class).toInstance(config);
				bind(MouseManager.class).toInstance(mouse);
				bind(ClientThread.class).toInstance(thread);
			}
		}).getInstance(ButtonGuard.class);
		guard.startUp();
	}

	private MenuEntry button(String option, int group)
	{
		MenuEntry e = TestMenus.entry(option, "", MenuAction.CC_OP, -1, group);
		Widget widget = mock(Widget.class);
		when(widget.getId()).thenReturn(group << 16);
		when(e.getWidget()).thenReturn(widget);
		return e;
	}

	private MenuOptionClicked click(MenuEntry e)
	{
		MenuOptionClicked event = mock(MenuOptionClicked.class);
		when(event.getMenuEntry()).thenReturn(e);
		guard.onMenuOptionClicked(event);
		return event;
	}

	@Test
	public void normalButtonsPassThrough()
	{
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE)), never()).consume();
	}

	@Test
	public void disabledButtonsConsumeEvenFromOpenMenu()
	{
		when(config.autoRetaliate()).thenReturn(ClickMode.DISABLED);
		press(true);
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
	}

	private void press(boolean open)
	{
		press(open, false);
	}

	private void press(boolean open, boolean shift)
	{
		when(client.isMenuOpen()).thenReturn(open);
		listener.get().mousePressed(new MouseEvent(new Canvas(), MouseEvent.MOUSE_PRESSED, 1,
				shift ? MouseEvent.SHIFT_DOWN_MASK : 0, 1, 1, 1, false, MouseEvent.BUTTON1));
	}

	@Test
	public void rightClickOnlyBlocksDirectLeftClick()
	{
		when(config.autoRetaliate()).thenReturn(ClickMode.LEFT_CLICK_OFF);
		press(false);
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
	}

	@Test
	public void rightClickOnlyAllowsSelectionFromOpenMenu()
	{
		when(config.autoRetaliate()).thenReturn(ClickMode.LEFT_CLICK_OFF);
		press(true);
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE)), never()).consume();
	}

	@Test
	public void selectionOriginIsConsumedOnce()
	{
		when(config.autoRetaliate()).thenReturn(ClickMode.LEFT_CLICK_OFF);
		press(true);
		click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE));
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
	}

	@Test
	public void resetClearsStaleMouseOrigin()
	{
		when(config.autoRetaliate()).thenReturn(ClickMode.LEFT_CLICK_OFF);
		press(true);
		guard.reset();
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
	}

	@Test
	public void labelsCannotProtectUnrelatedWidget()
	{
		when(config.autoRetaliate()).thenReturn(ClickMode.DISABLED);
		assertNull(GuardedAction.find(button("Auto Retaliate", InterfaceID.INVENTORY)));
	}

	@Test
	public void allFourGameframeModesMatchXpControls()
	{
		for (int group : new int[] { InterfaceID.ORBS, InterfaceID.ORBS_NOMAP, InterfaceID.ORBS_OSM,
				InterfaceID.ORBS_OSM_NOMAP })
		{
			assertNotNull(GuardedAction.find(button("Show XP drops", group)));
		}
	}

	@Test
	public void bankAndBothReportActionsMatch()
	{
		assertNotNull(GuardedAction.find(button("Always set placeholders", InterfaceID.BANKMAIN)));
		assertNotNull(GuardedAction.find(button("Report abuse", InterfaceID.CHATBOX)));
		assertNotNull(GuardedAction.find(button("Report game bug", InterfaceID.CHATBOX)));
	}

	@Test
	public void disabledRemovedWithStableRetainedOrder()
	{
		when(config.report()).thenReturn(ClickMode.DISABLED);
		MenuEntry cancel = TestMenus.entry("Cancel", "", MenuAction.CANCEL, -1, 0),
				report = button("Report abuse", InterfaceID.CHATBOX), other = button("Settings", InterfaceID.CHATBOX);
		Menu m = TestMenus.menu(cancel, report, other);
		when(client.getMenu()).thenReturn(m);
		guard.onPostMenuSort(new PostMenuSort());
		assertArrayEquals(new MenuEntry[] { cancel, other }, m.getMenuEntries());
	}

	@Test
	public void tooltipRestoresOwnedInstanceAndNeverTouchesReplacement()
	{
		when(config.autoRetaliate()).thenReturn(ClickMode.DISABLED);
		Widget original = mock(Widget.class), replacement = mock(Widget.class);
		Menu menu = TestMenus.menu(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE));
		when(client.getWidget(InterfaceID.CombatInterface.TOOLTIP)).thenReturn(original);
		when(client.getMenu()).thenReturn(menu);
		guard.onPostMenuSort(new PostMenuSort());
		verify(original).setHidden(true);
		when(client.getWidget(InterfaceID.CombatInterface.TOOLTIP)).thenReturn(replacement);
		guard.reset();
		verify(original).setHidden(false);
		verify(replacement, never()).setHidden(anyBoolean());
	}

	@Test
	public void alreadyHiddenTooltipRemainsHiddenOnShutdown()
	{
		when(config.autoRetaliate()).thenReturn(ClickMode.DISABLED);
		Widget tooltip = mock(Widget.class);
		when(tooltip.isHidden()).thenReturn(true);
		Menu menu = TestMenus.menu(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE));
		when(client.getWidget(InterfaceID.CombatInterface.TOOLTIP)).thenReturn(tooltip);
		when(client.getMenu()).thenReturn(menu);
		guard.onPostMenuSort(new PostMenuSort());
		guard.shutDown();
		verify(tooltip, never()).setHidden(false);
		verify(mouse).unregisterMouseListener(listener.get());
	}

	@Test
	public void nonWidgetActionsNeverMatch()
	{
		MenuEntry e = button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE);
		when(e.getType()).thenReturn(MenuAction.NPC_FIRST_OPTION);
		assertNull(GuardedAction.find(e));
	}

	@Test
	public void shiftRequirementBlocksBothDirectAndMenuClicksWithoutShift()
	{
		when(config.autoRetaliateRequireShift()).thenReturn(true);
		for (boolean open : new boolean[] { false, true })
		{
			press(open, false);
			verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
		}
	}

	@Test
	public void shiftAtPhysicalClickAllowsNativeActionEvenIfReleasedBeforeDispatch()
	{
		when(config.autoRetaliateRequireShift()).thenReturn(true);
		when(client.isKeyPressed(KeyCode.KC_SHIFT)).thenReturn(false);
		for (boolean open : new boolean[] { false, true })
		{
			press(open, true);
			MenuEntry entry = button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE);
			verify(click(entry), never()).consume();
			verify(entry, never()).setOption(anyString());
			verify(entry, never()).setType(any(MenuAction.class));
		}
	}

	@Test
	public void pressingShiftAfterTheClickDoesNotUnlockIt()
	{
		when(config.autoRetaliateRequireShift()).thenReturn(true);
		press(false, false);
		when(client.isKeyPressed(KeyCode.KC_SHIFT)).thenReturn(true);
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
	}

	@Test
	public void shiftDoesNotOverrideHiddenOrRightClickOnlyProtection()
	{
		when(config.autoRetaliateRequireShift()).thenReturn(true);
		when(config.autoRetaliate()).thenReturn(ClickMode.DISABLED);
		press(true, true);
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
		when(config.autoRetaliate()).thenReturn(ClickMode.LEFT_CLICK_OFF);
		press(false, true);
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
		press(true, true);
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE)), never()).consume();
	}

	@Test
	public void shiftProtectionDoesNotApplyToOtherButtonsOrWidgets()
	{
		when(config.autoRetaliateRequireShift()).thenReturn(true);
		press(false, false);
		verify(click(button("Show XP drops", InterfaceID.ORBS)), never()).consume();
		press(false, false);
		verify(click(button("Auto Retaliate", InterfaceID.INVENTORY)), never()).consume();
	}

	@Test
	public void shiftSnapshotIsConsumedOnceAndClearedByReset()
	{
		when(config.autoRetaliateRequireShift()).thenReturn(true);
		press(false, true);
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE)), never()).consume();
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
		press(false, true);
		guard.reset();
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
	}

	@Test
	public void revealKeyDoesNotBypassExplicitShiftRequirement()
	{
		when(config.autoRetaliateRequireShift()).thenReturn(true);
		Canvas canvas = mock(Canvas.class);
		when(canvas.hasFocus()).thenReturn(true);
		when(client.getCanvas()).thenReturn(canvas);
		when(config.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.CONTROL);
		when(client.isKeyPressed(KeyCode.KC_CONTROL)).thenReturn(true);
		press(false, false);
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE))).consume();
	}

	@Test
	public void noObservedMousePressUsesCurrentShiftState()
	{
		when(config.autoRetaliateRequireShift()).thenReturn(true);
		when(client.isKeyPressed(KeyCode.KC_SHIFT)).thenReturn(true);
		verify(click(button("Auto Retaliate", InterfaceID.COMBAT_INTERFACE)), never()).consume();
	}

	@Test
	public void auditAllButtonModesWithCleanupAndClickOrigins()
	{
		MenuEngine engine = Guice.createInjector(new AbstractModule()
		{
			protected void configure()
			{
				bind(Client.class).toInstance(client);
				bind(ImprovedMenusConfig.class).toInstance(config);
				bind(net.runelite.client.game.ItemManager.class)
						.toInstance(mock(net.runelite.client.game.ItemManager.class));
			}
		}).getInstance(MenuEngine.class);
		when(config.itemRules()).thenReturn("");
		when(config.colors()).thenReturn("");
		when(config.exceptions()).thenReturn("");
		engine.reload();
		String[] options = { "Auto Retaliate", "Show XP drops", "Always set placeholders", "Report abuse" };
		int[] groups = { InterfaceID.COMBAT_INTERFACE, InterfaceID.ORBS, InterfaceID.BANKMAIN, InterfaceID.CHATBOX };
		int cases = 0;
		for (ClickMode mode : ClickMode.values())
			for (int settings = 0; settings < 8; settings++)
				for (int target = 0; target < 4; target++)
					for (boolean fromMenu : new boolean[] { false, true })
					{
						when(config.autoRetaliate()).thenReturn(mode);
						when(config.xpDrops()).thenReturn(mode);
						when(config.alwaysSetPlaceholders()).thenReturn(mode);
						when(config.report()).thenReturn(mode);
						when(config.hideCancel()).thenReturn((settings & 1) != 0);
						when(config.hideWalkHere()).thenReturn((settings & 2) != 0);
						when(config.deprioritizeLeftClickOffEntries()).thenReturn((settings & 4) != 0);
						MenuEntry entry = button(options[target], groups[target]),
								cancel = TestMenus.entry("Cancel", "", MenuAction.CANCEL, -1, 0);
						Menu menu = TestMenus.menu(cancel, entry);
						when(client.getMenu()).thenReturn(menu);
						when(client.isMenuOpen()).thenReturn(false);
						guard.onPostMenuSort(new PostMenuSort());
						guard.onMenuOpened(new MenuOpened());
						engine.applyOpened(menu);
						assertTrue("Cleanup must retain a safe fallback", menu.getMenuEntries().length > 0);
						press(fromMenu);
						MenuOptionClicked event = click(entry);
						if (mode.removesMenuEntry() || mode.blocksLeftClick() && !fromMenu)
							verify(event).consume();
						else
							verify(event, never()).consume();
						guard.reset();
						cases++;
					}
		guard.shutDown();
		System.out.println("AUDIT button protection/cleanup/origin cases=" + cases);
	}
}

package com.improvedmenus;

import com.improvedmenus.rs2f.LootFilter;
import com.improvedmenus.rs2f.model.*;
import com.google.gson.Gson;
import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import org.junit.Assume;
import static org.junit.Assert.*;

public class ComplexIconTest
{
	private ItemFacts fact(int account, int ownership, int quantity, long price)
	{
		return ItemFacts.builder().id(385).name("Shark").quantity(quantity).accountType(account).ownership(ownership)
				.gePrice(price).haPrice(50).tradeable(true).geTradeable(true).worldPoint(new WorldPoint(3200, 3200, 0))
				.build();
	}

	@Test
	public void macrosApplyAndTerminalOrdering()
	{
		String source = "#define FOOD(name_) (name:name_)\n#define STYLE icon=Sprite(41,0);\napply (true) {icon=Item(995);} rule (FOOD(\"Shark\") && quantity:>=2) { STYLE } rule (true) {icon=CurrentItem();}";
		LootFilter f = LootFilter.compile(source);
		assertEquals(new BufferedImageProvider.Sprite(41, 0), f.find(fact(0, 1, 2, 100)));
		assertEquals(new BufferedImageProvider.CurrentItem(), f.find(fact(0, 1, 1, 100)));
	}

	@Test
	public void hiddenTerminalSuppressesInheritedIconAndStops()
	{
		LootFilter f = LootFilter.compile(
				"apply (true) {icon=Item(995);} rule(name:\"Shark\") {hidden=true;} rule(true) {icon=Sprite(41,0);}");
		assertNull(f.find(fact(0, 1, 1, 10)));
	}

	@Test
	public void finalVisibilityOverridesAndCompactFollowFilterMerging()
	{
		ItemFacts item = fact(0, 1, 1, 10);
		assertNull(LootFilter.compile("rule(true) {textColor=\"#ffffff\";}").find(item));
		assertNull(LootFilter.compile("apply(true) {icon=Item(995);} rule(true) {hideOverlay=true;}").find(item));
		assertEquals(new BufferedImageProvider.Item(995), LootFilter.compile(
				"apply(true) {icon=Item(995); hidden=true; hideOverlay=true;} rule(true) {hidden=false; hideOverlay=false;}")
				.find(item));
		assertNull(LootFilter
				.compile("apply(true) {icon=Item(995); hidden=true; hideOverlay=true;} rule(true) {hidden=false;}")
				.find(item));
		com.improvedmenus.rs2f.FilterRule always = LootFilter.compile("rule(true) {icon=Item(995);}").rules.get(0);
		LootFilter compact = LootFilter.builder().addRule(new com.improvedmenus.rs2f.FilterRule(always.getCond(),
				com.improvedmenus.rs2f.DisplayConfig.builder().compact(true).build(), true, 0)).build();
		assertEquals(new BufferedImageProvider.CurrentItem(), compact.find(item));

	}

	@Test
	public void ironmanOwnershipAndAreaAreLiveConditions()
	{
		LootFilter f = LootFilter.compile(
				"rule(accountType:1 && !ownership:2 && area:[3190,3190,0,3210,3210,0]) {icon=File(\"food/heart.png\");} rule(true) {icon=CurrentItem();}");
		assertEquals(new BufferedImageProvider.File("food/heart.png"), f.find(fact(1, 1, 1, 100)));
		assertEquals(new BufferedImageProvider.CurrentItem(), f.find(fact(0, 1, 1, 100)));
		assertEquals(new BufferedImageProvider.CurrentItem(), f.find(fact(1, 2, 1, 100)));
	}

	@Test
	public void valueUsesStackQuantityAndWildcard()
	{
		LootFilter f = LootFilter.compile(
				"rule(name:\"*hark\" && gevalue:>=200 && tradeable:true && geTradeable:true && !noted:true) {icon=Item(995);}");
		assertNotNull(f.find(fact(0, 1, 2, 100)));
		assertNull(f.find(fact(0, 1, 1, 100)));
	}

	@Test
	public void rejectsMalformedAndExpansionBombs()
	{
		try
		{
			LootFilter.compile("rule (true) {icon=File(\"x\");");
			fail();
		}
		catch (IllegalArgumentException expected)
		{
		}
		StringBuilder source = new StringBuilder("#define A0 true\n");
		for (int i = 1; i < 24; i++)
			source.append("#define A").append(i).append(" A").append(i - 1).append(" || A").append(i - 1).append("\n");
		source.append("rule(A23) {icon=CurrentItem();}");
		try
		{
			LootFilter.compile(source.toString());
			fail();
		}
		catch (IllegalArgumentException expected)
		{
		}
	}

	@Test
	public void invalidIconIdsRejectBeforeSaving()
	{
		for (String source : new String[] { "rule(true) {icon=Item(-1);}", "rule(true) {icon=Sprite(41,-1);}" })
		{
			try
			{
				LootFilter.compile(source);
				fail();
			}
			catch (IllegalArgumentException expected)
			{
			}
		}
	}

	@Test
	public void imageCopyPreservesTransparencyAndRejectsTraversal() throws Exception
	{
		BufferedImage input = new BufferedImage(40, 20, BufferedImage.TYPE_INT_ARGB);
		input.setRGB(20, 10, 0xffff0000);
		String image = IconImages.encode(input);
		BufferedImage decoded = IconImages.decode(image);
		assertEquals(17, decoded.getWidth());
		assertEquals(15, decoded.getHeight());
		assertEquals(0, decoded.getRGB(0, 0));
		for (String name : new String[] { "../x.png", "/x.png", "C:\\x.png", "folder/../x.png", "a//b.png" })
		{
			try
			{
				IconImages.safeName(name);
				fail(name);
			}
			catch (IllegalArgumentException expected)
			{
			}
		}
	}

	@Test
	public void backupContainsSourceAndImagesAndChecksMissingFiles() throws Exception
	{
		FilterIcons filters = new FilterIcons();
		filters.gson = new Gson();
		FilterIcons.Bundle b = new FilterIcons.Bundle();
		b.compressedSource = FilterIcons.compress("rule(true) {icon=File(\"heart.png\");}");
		try
		{
			filters.prepare(b);
			fail();
		}
		catch (IllegalArgumentException expected)
		{
		}
		b.images.put("heart.png", IconImages.encode(new BufferedImage(17, 15, BufferedImage.TYPE_INT_ARGB)));
		FilterIcons.Prepared p = filters.parse(filters.gson.toJson(b));
		assertEquals(1, p.images.size());
		assertEquals(1, p.program.rules.size());
		assertTrue(FilterIcons.source(p.bundle).contains("heart.png"));
	}

	private void preset(String name) throws Exception
	{
		String dir = System.getProperty("filterFixtures", "");
		Assume.assumeFalse(dir.isEmpty());
		String text = Files.readString(Paths.get(dir, name + ".rs2f"));
		LootFilter f = LootFilter.compile(text);
		assertTrue(f.rules.size() > 20);
		System.out.println(name + ": " + f.rules.size() + " rules, " + f.files().size() + " file icons");
		for (int acc = 0; acc < 4; acc++)
			for (int owner = 0; owner < 4; owner++)
				f.find(fact(acc, owner, 5, 100));
	}

	@Test
	public void suppliedFilterscapePreset() throws Exception
	{
		preset("filterscape");
	}

	@Test
	public void suppliedJoePreset() throws Exception
	{
		preset("joe");
	}

	@Test
	public void suppliedIronmanPreset() throws Exception
	{
		preset("ironman");
	}
}

package com.improvedmenus;

import com.improvedmenus.ImprovedMenusConfig.CustomIconProvider;
