		when(scene.getTiles()).thenReturn(new Tile[][][] { { { tile } } });
		when(tile.getLocalLocation()).thenReturn(new LocalPoint(64, 64));
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getName()).thenReturn("Shark");
		when(composition.getLinkedNoteId()).thenReturn(-1);
		when(composition.getNote()).thenReturn(-1);
		when(filter.items.getItemComposition(385)).thenReturn(composition);
