	private static BufferedImage solid(Color color)
	{
		BufferedImage image = new BufferedImage(17, 15, BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < 15; y++)
			for (int x = 0; x < 17; x++)
				image.setRGB(x, y, color.getRGB());
