import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.AsyncBufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;

public class LootFilterAsyncImageTest
{
	private final List<Runnable> tasks = new ArrayList<>();
	private final LootFilterImageCache cache = new LootFilterImageCache(tasks::add);
	private final Map<String, Object> key = Map.of("type", "item", "id", 4151);

	@Test
	public void waitsForPixelsAndCopiesOnClientThread()
	{
		AsyncBufferedImage source = image(36, 32);
		AtomicInteger calls = new AtomicInteger();
		Supplier<?> provider = () ->
		{
			calls.incrementAndGet();
			return source;
		};
		assertNull(cache.get(key, provider));
		assertNull(cache.get(key, provider));
		assertEquals(1, calls.get());
		fill(source, Color.CYAN);
		source.loaded();
		assertNull(cache.get(key, provider));
		drain();
		BufferedImage result = cache.get(key, provider);
		assertEquals(17, result.getWidth());
		assertEquals(15, result.getHeight());
		assertEquals(Color.CYAN.getRGB(), result.getRGB(8, 7));
		assertNotSame(source, result);
		assertEquals(1, calls.get());
	}

	@Test
	public void alreadyLoadedSmallImagesAreCopiedWithoutChangingAlpha()
	{
		AsyncBufferedImage source = image(4, 4);
		source.setRGB(1, 1, 0x804080c0);
		source.loaded();
		assertNull(cache.get(key, () -> source));
		drain();
		BufferedImage result = cache.get(key, () -> source);
		assertNotSame(source, result);
		assertEquals(0x804080c0, result.getRGB(1, 1));
		source.setRGB(1, 1, Color.RED.getRGB());
		assertEquals(0x804080c0, result.getRGB(1, 1));
		result.setRGB(0, 0, Color.BLUE.getRGB());
		assertEquals(0, source.getRGB(0, 0));
	}

	@Test
	public void oldFilterCompletionCannotReplaceNewIcon()
	{
		AsyncBufferedImage old = image(4, 4);
		AsyncBufferedImage current = image(4, 4);
		assertNull(cache.get(key, () -> old));
		cache.clear();
		assertNull(cache.get(key, () -> current));
		fill(current, Color.GREEN);
		current.loaded();
		drain();
		BufferedImage result = cache.get(key, () -> current);
		long revision = cache.revision();
		fill(old, Color.RED);
		old.loaded();
		drain();
		assertSame(result, cache.get(key, () -> current));
		assertEquals(Color.GREEN.getRGB(), result.getRGB(1, 1));
		assertEquals(revision, cache.revision());
	}

	@Test
	public void evictedRequestsCannotChangeRevisionOrReplaceEntries()
	{
		AsyncBufferedImage first = image(2, 2);
		assertNull(cache.get(key, () -> first));
		for (int id = 0; id < 128; id++)
		{
			AsyncBufferedImage pending = image(2, 2);
			assertNull(cache.get(Map.of("type", "sprite", "id", id), () -> pending));
		}
		long revision = cache.revision();
		first.loaded();
		drain();
		assertEquals(revision, cache.revision());
		assertNull(cache.get(key, () -> image(2, 2)));
	}

	@Test
	public void unavailableImageCanBeRequestedAgainAfterInvalidation()
	{
		assertNull(cache.get(key, () -> null));
		cache.clear();
		AsyncBufferedImage source = image(2, 2);
		source.loaded();
		assertNull(cache.get(key, () -> source));
		drain();
		assertEquals(2, cache.get(key, () -> source).getWidth());
	}

	private AsyncBufferedImage image(int width, int height)
	{
		ClientThread thread = mock(ClientThread.class);
		doAnswer(call ->
		{
			tasks.add(call.getArgument(0));
			return null;
		}).when(thread).invokeLater(any(Runnable.class));
		return new AsyncBufferedImage(thread, width, height, BufferedImage.TYPE_INT_ARGB);
	}

	private void drain()
	{
		while (!tasks.isEmpty())
		{
			tasks.remove(0).run();
		}
	}

	private void fill(BufferedImage image, Color color)
	{
		var graphics = image.createGraphics();
		graphics.setColor(color);
		graphics.fillRect(0, 0, image.getWidth(), image.getHeight());
		graphics.dispose();
	}
}

package com.improvedmenus;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;
import org.junit.Test;
import static org.junit.Assert.*;

public class LootFilterImageProviderTest
{
	@Test
	public void largeProviderImagesAreRetainedOnlyAtMenuSize()
	{
		var cache = new LootFilterImageCache(Runnable::run);
		BufferedImage original = new BufferedImage(512, 512, BufferedImage.TYPE_INT_ARGB);
		var graphics = original.createGraphics();
		graphics.setColor(Color.MAGENTA);
		graphics.fillRect(0, 0, 512, 512);
		graphics.dispose();
		BufferedImage image = cache.get(Map.of("type", "file", "filename", "large.png"),
				() -> CompletableFuture.completedFuture(original));
		assertEquals(17, image.getWidth());
		assertEquals(15, image.getHeight());
		assertEquals(Color.MAGENTA.getRGB(), image.getRGB(8, 7));
		assertEquals(512, original.getWidth());
		assertNotSame(original, image);
	}

	@Test
	public void lateResultsCannotRepopulateCacheAfterReload()
	{
		List<Runnable> client = new ArrayList<>();
		var cache = new LootFilterImageCache(client::add);
		Map<String, Object> key = Map.of("type", "file", "filename", "heart.png");
		CompletableFuture<BufferedImage> old = new CompletableFuture<>(), fresh = new CompletableFuture<>();
		assertNull(cache.get(key, () -> old));
		cache.clear();
		assertNull(cache.get(key, () -> fresh));
		BufferedImage oldImage = new BufferedImage(2, 2, 2), newImage = new BufferedImage(2, 2, 2);
		old.complete(oldImage);
		fresh.complete(newImage);
		assertEquals(2, client.size());
		client.forEach(Runnable::run);
		BufferedImage cached = cache.get(key, () ->
		{
			throw new AssertionError("Should reuse completed image");
		});
		assertNotSame(newImage, cached);
		assertEquals(newImage.getRGB(0, 0), cached.getRGB(0, 0));
	}

	@Test
	public void pendingRequestsAreDeduplicatedAndFailureDoesNotEscape()
	{
		var cache = new LootFilterImageCache(Runnable::run);
		AtomicInteger calls = new AtomicInteger();
		var key = Map.<String, Object>of("type", "sprite", "id", 123, "index", 0);
		var pending = new CompletableFuture<BufferedImage>();
		Supplier<?> provider = () ->
		{
			calls.incrementAndGet();
			return pending;
		};
		for (int i = 0; i < 20; i++)
			assertNull(cache.get(key, provider));
		assertEquals(1, calls.get());
		pending.completeExceptionally(new IllegalArgumentException());
		assertNull(cache.get(key, provider));
		cache.clear();
		assertNull(cache.get(key, () ->
		{
			throw new IllegalStateException();
		}));
	}

	@Test
	public void visibilityAndDescriptorDoNotInvokeProviderDuringDecode()
	{
		AtomicInteger calls = new AtomicInteger();
		Supplier<?> provider = () ->
		{
			calls.incrementAndGet();
			return CompletableFuture.completedFuture(new BufferedImage(2, 2, 2));
		};
		Map<String, Object> display = new HashMap<>();
		display.put("hidden", false);
		display.put("hideOverlay", false);
		display.put("menuSort", -1);
		display.put("menuTextColor", Color.CYAN);
		display.put("icon",
				Map.of("type", "current-item", "id", 385, "quantity", 1, "height", 16, "getImage", provider));
		Map<String, Object> data = Map.of("status", "ok", "display", display);
		var visible = LootFiltersCompatibility.decode(data, 385);
		assertTrue(visible.itemIcon);
		assertTrue(visible.hasIcon());
		assertEquals(Color.CYAN, visible.menuColor);
		assertEquals(-1, visible.menuSort);
		display.put("hideOverlay", true);
		assertFalse(LootFiltersCompatibility.decode(data, 385).hasIcon());
		display.put("hideOverlay", false);
		display.put("hidden", true);
		assertFalse(LootFiltersCompatibility.decode(data, 385).hasIcon());
		assertEquals(0, calls.get());
		assertNull(LootFiltersCompatibility.decode(Map.of("status", "ambiguous"), 385));
	}
}

package com.improvedmenus;

import java.awt.Color;
import net.runelite.api.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class LootFiltersMenuPresentationTest
{
	@Test
	public void asynchronousRedecorationRestoresColorsAndIconSpacing() throws Exception
	{
		when(config.useLootFiltersInMenu()).thenReturn(true);
		when(config.lootFiltersMenuColors()).thenReturn(true);
		when(config.groundIcons()).thenReturn(true);
		when(config.groundIconSource()).thenReturn(ImprovedMenusConfig.GroundIconSource.NATIVE);
		MenuEntry item = take("Shark", 385, 1, false);
		Menu menu = TestMenus.menu(item);
		Client client = mock(Client.class);
		when(client.getMenu()).thenReturn(menu);
		var icons = mock(net.runelite.client.game.ChatIconManager.class);
		when(icons.chatIconIndex(anyInt())).thenReturn(42);
		MenuPresentation iconPresentation = new MenuPresentation();
		field(iconPresentation, "client", client);
		field(iconPresentation, "config", config);
		field(iconPresentation, "icons", icons);
		iconPresentation.start();
		ImprovedMenusPlugin plugin = new ImprovedMenusPlugin();
		field(plugin, "client", client);
		field(plugin, "presentation", iconPresentation);
		field(plugin, "playerBadges",
				new PlayerMenuBadges(client, config, icons, mock(net.runelite.client.party.PartyService.class),
						mock(net.runelite.client.ui.overlay.tooltip.TooltipManager.class)));
		field(plugin, "lootMenu", presentation);
		field(plugin, "lootCompatibility", compatibility);
		var decorate = ImprovedMenusPlugin.class.getDeclaredMethod("decorateMenu");
		decorate.setAccessible(true);
		for (int i = 0; i < 3; i++)
		{
			decorate.invoke(plugin);
			assertEquals("<img=42><col=00ffff>Shark</col>", item.getTarget());
		}
		when(config.lootFiltersMenuColors()).thenReturn(false);
		decorate.invoke(plugin);
		assertEquals("<img=42><col=ff0000>Shark</col>", item.getTarget());
		iconPresentation.stop();
		presentation.stop();
		assertEquals("<col=ff0000>Shark</col>", item.getTarget());
	}

	private static void field(Object object, String name, Object value) throws Exception
	{
		var field = object.getClass().getDeclaredField(name);
		field.setAccessible(true);
		field.set(object, value);
	}

	private final ImprovedMenusConfig config = mock(ImprovedMenusConfig.class);
	private final LootFiltersCompatibility compatibility = mock(LootFiltersCompatibility.class);
	private final LootFiltersMenuPresentation presentation = com.google.inject.Guice
			.createInjector(new com.google.inject.AbstractModule()
			{
				protected void configure()
				{
					bind(Client.class).toInstance(mock(Client.class));
					bind(ImprovedMenusConfig.class).toInstance(config);
					bind(LootFiltersCompatibility.class).toInstance(compatibility);
				}
			}).getInstance(LootFiltersMenuPresentation.class);

	private MenuEntry take(String name, int id, int sort, boolean hidden)
	{
		MenuEntry entry = TestMenus.entry("<col=00ff00>Take</col>", "<col=ff0000>" + name + "</col>",
				MenuAction.GROUND_ITEM_THIRD_OPTION, id, 0);
		when(entry.getIdentifier()).thenReturn(id);
		when(entry.isDeprioritized()).thenReturn(hidden);
		when(compatibility.find(entry))
				.thenReturn(new LootFiltersCompatibility.Result(null, false, hidden, hidden, sort, Color.CYAN));
		return entry;
	}

	@Test
	public void defaultsAndDisabledIntegrationLeaveMenuUntouched()
	{
		ImprovedMenusConfig defaults = new ImprovedMenusConfig()
		{
		};
		assertFalse(defaults.useLootFiltersInMenu());
		assertFalse(defaults.lootFiltersMenuColors());
		assertFalse(defaults.lootFiltersCompatibility());
		assertEquals(ImprovedMenusConfig.CustomIconProvider.OFF, defaults.customIconProvider());
		assertEquals("OFF", SettingsCatalog.ALL.get("customIconProvider").defaultValue);
		assertEquals(ImprovedMenusConfig.GroundIconSource.NATIVE, defaults.groundIconSource());
		assertEquals("false", SettingsCatalog.ALL.get("useLootFiltersInMenu").defaultValue);
		assertEquals("false", SettingsCatalog.ALL.get("lootFiltersMenuColors").defaultValue);
		MenuEntry item = take("Shark", 385, 100, true);
		clearInvocations(compatibility);
		Menu menu = TestMenus.menu(item);
		presentation.apply(menu);
		verifyNoInteractions(compatibility);
		verify(menu, never()).setMenuEntries(any());
		assertEquals("<col=ff0000>Shark</col>", item.getTarget());
	}

	@Test
	public void sortingPreservesObjectsPlayersUnresolvedItemsAndEveryAction()
	{
		when(config.useLootFiltersInMenu()).thenReturn(true);
		MenuEntry high = take("High", 1, Integer.MAX_VALUE, false), low = take("Low", 2, Integer.MIN_VALUE, false),
				hidden = take("Hidden", 3, 500, true);
		MenuEntry object = TestMenus.entry("Open", "Chest", MenuAction.GAME_OBJECT_FIRST_OPTION, 9, 0);
		MenuEntry player = TestMenus.entry("Follow", "Player", MenuAction.PLAYER_FIRST_OPTION, 10, 0);
		MenuEntry missing = take("Unknown", 4, 2, false);
		when(compatibility.find(missing)).thenReturn(null);
		MenuEntry cancel = TestMenus.entry("Cancel", "", MenuAction.CANCEL, 0, 0);
		MenuEntry[] original = { cancel, high, object, missing, low, player, hidden };
		Menu menu = TestMenus.menu(original);
		presentation.apply(menu);
		assertArrayEquals(new MenuEntry[] { cancel, hidden, object, missing, low, player, high },
				menu.getMenuEntries());
		assertEquals("<col=ff0000>High</col>", high.getTarget());
		assertEquals("<col=00ff00>Take</col>", high.getOption());
		verify(compatibility, never()).find(object);
		verify(compatibility, never()).find(player);
		for (MenuEntry e : original)
		{
			verify(e, never()).setType(any());
			verify(e, never()).setDeprioritized(anyBoolean());
		}
		presentation.stop();
		assertArrayEquals(original, menu.getMenuEntries());
	}

	@Test
	public void lootSortingAndAsynchronousRefreshKeepExamineBelowDeprioritizedTakes()
	{
		when(config.useLootFiltersInMenu()).thenReturn(true);
		MenuEntry low = take("Low", 1, 1, false), high = take("High", 2, 100, false),
				hidden = take("Hidden", 3, 500, true);
		MenuEntry examine = TestMenus.entry("Examine", "High", MenuAction.EXAMINE_ITEM_GROUND, 2, 0);
		MenuEntry walk = TestMenus.entry("Walk here", "", MenuAction.WALK, -1, 0);
		MenuEntry cancel = TestMenus.entry("Cancel", "", MenuAction.CANCEL, -1, 0);
		Menu menu = TestMenus.menu(cancel, hidden, examine, walk, high, low);
		GroundMenuGroups.examineLast(menu);
		MenuEntry[] grouped = menu.getMenuEntries().clone();
		for (int i = 0; i < 3; i++)
		{
			presentation.apply(menu);
			assertArrayEquals(new MenuEntry[] { cancel, examine, hidden, walk, low, high }, menu.getMenuEntries());
		}
		presentation.stop();
		assertArrayEquals(grouped, menu.getMenuEntries());
	}

	@Test
	public void colorsAreSeparatelyOptedInAndRestoredWithoutLosingOtherTags()
	{
		when(config.useLootFiltersInMenu()).thenReturn(true);
		MenuEntry item = take("Shark", 385, 1, false);
		item.setTarget("<img=5><col=ff0000>Shark (2)</col>");
		Menu menu = TestMenus.menu(item);
		presentation.apply(menu);
		assertEquals("<img=5><col=ff0000>Shark (2)</col>", item.getTarget());
		when(config.lootFiltersMenuColors()).thenReturn(true);
		presentation.apply(menu);
		assertEquals("<col=00ffff><img=5>Shark (2)</col>", item.getTarget());
		assertEquals("<col=00ff00>Take</col>", item.getOption());
		presentation.stop();
		assertEquals("<img=5><col=ff0000>Shark (2)</col>", item.getTarget());
		presentation.apply(menu);
		item.setTarget("Other plugin edit");
		presentation.stop();
		assertEquals("Other plugin edit", item.getTarget());
	}

	@Test
	public void hiddenRowsKeepExistingColorAndPriorityEvenWhenColorsAreEnabled()
	{
		when(config.useLootFiltersInMenu()).thenReturn(true);
		when(config.lootFiltersMenuColors()).thenReturn(true);
		MenuEntry hidden = take("Hidden", 3, 5, true), visible = take("Visible", 4, 1, false);
		when(hidden.isDeprioritized()).thenReturn(false);
		Menu menu = TestMenus.menu(hidden, visible);
		presentation.apply(menu);
		assertArrayEquals(new MenuEntry[] { visible, hidden }, menu.getMenuEntries());
		assertEquals("<col=ff0000>Hidden</col>", hidden.getTarget());
		verify(hidden, never()).setDeprioritized(anyBoolean());
	}

	@Test
	public void cleanupDoesNotUndoOtherPluginOrderingOrReusedEntryIdentity()
	{
		when(config.useLootFiltersInMenu()).thenReturn(true);
		when(config.lootFiltersMenuColors()).thenReturn(true);
		MenuEntry high = take("High", 1, 5, false), low = take("Low", 2, 1, false);
		Menu menu = TestMenus.menu(high, low);
		presentation.apply(menu);
		menu.setMenuEntries(new MenuEntry[] { high });
		when(high.getWorldViewId()).thenReturn(2);
		String decorated = high.getTarget();
		presentation.stop();
		assertArrayEquals(new MenuEntry[] { high }, menu.getMenuEntries());
		assertEquals(decorated, high.getTarget());
	}
}

