		renderer.onBeforeMenuRender(event);
		assertFalse(event.isConsumed());
		when(config.menuTheme()).thenReturn(ImprovedMenusConfig.MenuTheme.OSRS);
		when(client.isMenuOpen()).thenReturn(false);
		renderer.onBeforeMenuRender(event);
		assertFalse(event.isConsumed());
		when(client.isMenuOpen()).thenReturn(true);
		when(menu.getMenuWidth()).thenReturn(0);
		renderer.onBeforeMenuRender(event);
