	@Test
	public void pluginAndThemeRegisterWithTheRealEventBusAndCanBeRemoved()
	{
		EventBus bus = new EventBus(error ->
		{
			throw new AssertionError(error);
		});
		ImprovedMenusPlugin plugin = new ImprovedMenusPlugin();
		bus.register(plugin);
		bus.register(renderer);
		BeforeMenuRender event = new BeforeMenuRender();
		bus.post(event);
		assertTrue(event.isConsumed());
		bus.unregister(renderer);
		bus.unregister(plugin);
		event = new BeforeMenuRender();
		bus.post(event);
		assertFalse(event.isConsumed());
		bus.register(plugin);
		bus.register(renderer);
		event = new BeforeMenuRender();
		bus.post(event);
		assertTrue(event.isConsumed());
		verify(client, times(2)).drawOriginalMenu(0);
	}

	@Test
