package com.improvedmenus;

import net.runelite.api.ChatMessageType;
import net.runelite.api.IconID;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObservedAccountBadgesTest
{
	@Test
	public void identifiesAllEightNativeBadgesAcrossIncomingPlayerChannels()
	{
		for (ChatMessageType type : new ChatMessageType[] { ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT,
				ChatMessageType.AUTOTYPER, ChatMessageType.MODAUTOTYPER, ChatMessageType.PRIVATECHAT,
				ChatMessageType.MODPRIVATECHAT, ChatMessageType.FRIENDSCHAT, ChatMessageType.CLAN_CHAT,
				ChatMessageType.CLAN_GUEST_CHAT, ChatMessageType.CLAN_GIM_CHAT })
		{
			ObservedAccountBadges cache = new ObservedAccountBadges();
			for (ObservedAccountBadges.Badge badge : ObservedAccountBadges.Badge.values())
			{
				cache.observe(type, "<col=ffffff>" + badge.icon + "Alice_Bob</col>");
				assertSame(type + ": " + badge, badge, cache.find("alice\u00a0bob"));
			}
		}
	}

	@Test
	public void outgoingPrivateChatAndSystemMessagesCannotMisidentifyTheRecipient()
	{
		ObservedAccountBadges cache = new ObservedAccountBadges();
		cache.observe(ChatMessageType.PUBLICCHAT, IconID.IRONMAN + "Alice");
		for (ChatMessageType type : new ChatMessageType[] { ChatMessageType.PRIVATECHATOUT, ChatMessageType.CONSOLE,
				ChatMessageType.GAMEMESSAGE, ChatMessageType.CLAN_MESSAGE, ChatMessageType.LOGINLOGOUTNOTIFICATION })
		{
			cache.observe(type, IconID.JAGEX_MODERATOR + "Alice");
			cache.observe(type, IconID.JAGEX_MODERATOR + "Bob");
			assertSame(ObservedAccountBadges.Badge.IRONMAN, cache.find("Alice"));
			assertNull(cache.find("Bob"));
		}
	}

	@Test
	public void latestChatUpdatesOrRemovesOldStatus()
	{
		ObservedAccountBadges cache = new ObservedAccountBadges();
		cache.observe(ChatMessageType.PUBLICCHAT, IconID.HARDCORE_IRONMAN + "Alice");
		cache.observe(ChatMessageType.PUBLICCHAT, IconID.IRONMAN + "Alice");
		assertSame(ObservedAccountBadges.Badge.IRONMAN, cache.find("Alice"));
		cache.observe(ChatMessageType.PUBLICCHAT, "Alice");
		assertNull(cache.find("Alice"));
	}

	@Test
	public void onlySupportedNativeAccountIconsAreRecognized()
	{
		ObservedAccountBadges cache = new ObservedAccountBadges();
		for (String name : new String[] { "Alice", "<img=999>Alice", "<img=22>Alice", "<img=110>Alice",
				"<img=210>Alice", "<img=-1>Alice", "<img=999999999999999>Alice", "<img=10x>Alice" })
		{
			cache.observe(ChatMessageType.PUBLICCHAT, name);
			assertNull(name, cache.find("Alice"));
		}
		cache.observe(ChatMessageType.PUBLICCHAT, "<img=999><img=2>Alice");
		assertSame(ObservedAccountBadges.Badge.IRONMAN, cache.find("Alice"));
	}

	@Test
	public void moderatorCrownTakesPrecedenceWhenMoreThanOneKnownIconExists()
	{
		assertSame(ObservedAccountBadges.Badge.PLAYER_MODERATOR,
				ObservedAccountBadges.fromName(IconID.IRONMAN.toString() + IconID.PLAYER_MODERATOR + "Alice"));
		assertSame(ObservedAccountBadges.Badge.JAGEX_MODERATOR,
				ObservedAccountBadges.fromName(IconID.PLAYER_MODERATOR.toString() + IconID.JAGEX_MODERATOR + "Alice"));
	}

	@Test
	public void invalidOrMissingNamesAreNotRemembered()
	{
		ObservedAccountBadges cache = new ObservedAccountBadges();
		for (String name : new String[] { null, "", "<img=2>", "<img=2>Alice!", "<img=2>ThisNameIsFarTooLong" })
		{
			cache.observe(ChatMessageType.PUBLICCHAT, name);
			assertNull(cache.find(name));
		}
		cache.observe(null, "<img=2>Alice");
		assertNull(cache.find("Alice"));
	}

	@Test
	public void observationsAreBoundedAndRecentlyUpdatedNamesSurviveEviction()
	{
		ObservedAccountBadges cache = new ObservedAccountBadges();
		for (int i = 0; i < ObservedAccountBadges.CAPACITY; i++)
			cache.observe(ChatMessageType.PUBLICCHAT, "<img=2>Player" + i);
		cache.observe(ChatMessageType.PUBLICCHAT, "<img=10>Player0");
		cache.observe(ChatMessageType.PUBLICCHAT, "<img=2>Newest");
		assertSame(ObservedAccountBadges.Badge.HARDCORE_IRONMAN, cache.find("Player0"));
		assertNull(cache.find("Player1"));
		assertSame(ObservedAccountBadges.Badge.IRONMAN, cache.find("Newest"));
		cache.clear();
		assertNull(cache.find("Newest"));
		assertNull(cache.find("Player0"));
	}
}

package com.improvedmenus;

import com.google.inject.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.tooltip.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class OptionCountOrderingTest
{
	@Test
	public void anchorsSurviveMouseHighlightAndRenderInSameFrame() throws Exception
	{
		Client client = mock(Client.class);
		ImprovedMenusConfig config = mock(ImprovedMenusConfig.class);
		RuneLiteConfig core = mock(RuneLiteConfig.class);
		when(core.overlayBackgroundColor()).thenReturn(Color.BLACK);
		when(client.getCanvasWidth()).thenReturn(500);
		when(client.getCanvasHeight()).thenReturn(300);
		when(client.getMouseCanvasPosition()).thenReturn(new net.runelite.api.Point(50, 50));
		net.runelite.api.Menu menu = TestMenus.menu(
				TestMenus.entry("Take", "Coins", MenuAction.GROUND_ITEM_FIRST_OPTION, -1, 0),
				TestMenus.entry("Examine", "Coins", MenuAction.EXAMINE_ITEM_GROUND, -1, 0));
		when(client.getMenu()).thenReturn(menu);
		when(config.optionCount()).thenReturn(true);
		when(config.countExamine()).thenReturn(true);
		when(config.countOnWidgets()).thenReturn(true);
		when(config.optionCountColor()).thenReturn("#ff0000");
		Injector injector = Guice.createInjector(new AbstractModule()
		{
			protected void configure()
			{
				bind(LootFiltersCompatibility.class).toInstance(mock(LootFiltersCompatibility.class));
				bind(java.util.concurrent.ScheduledExecutorService.class)
						.toInstance(mock(java.util.concurrent.ScheduledExecutorService.class));
				bind(Client.class).toInstance(client);
				bind(ImprovedMenusConfig.class).toInstance(config);
				bind(RuneLiteConfig.class).toInstance(core);
				bind(ItemManager.class).toInstance(mock(ItemManager.class));
				bind(ChatIconManager.class).toInstance(mock(ChatIconManager.class));
			}
		});
		TooltipManager manager = injector.getInstance(TooltipManager.class);
		Overlay producer = new Overlay()
		{
			public Dimension render(Graphics2D graphics)
			{

				manager.addFront(new Tooltip("<col=00ff00>Take Coins</col>"));
				return null;
			}
		};
		producer.setPosition(OverlayPosition.DYNAMIC);
		producer.setLayer(OverlayLayer.ABOVE_WIDGETS);
		OptionCountOverlay count = injector.getInstance(OptionCountOverlay.class);
		TooltipOverlay renderer = injector.getInstance(TooltipOverlay.class);
		List<Overlay> overlays = Arrays.asList(renderer, count, producer);
		Field comparator = OverlayManager.class.getDeclaredField("OVERLAY_COMPARATOR");
		comparator.setAccessible(true);
		overlays.sort((Comparator<Overlay>) comparator.get(null));
		assertEquals(Arrays.asList(producer, count, renderer), overlays);
		assertEquals(renderer.getLayer(), count.getLayer());
		for (boolean follow : new boolean[]{false, true})
		{
		when(config.followMenuStyle()).thenReturn(follow);
		injector.getInstance(MenuStyle.class).accept(new net.runelite.client.events.PluginMessage(MenuStyle.NAMESPACE, "style", MenuStyleTest.style(Color.RED)));
		for (ImprovedMenusConfig.CountAnchor anchor : ImprovedMenusConfig.CountAnchor.values())
		{
			when(config.countAnchor()).thenReturn(anchor);
			for (int frame = 0; frame < 2; frame++)
			{
				BufferedImage image = new BufferedImage(500, 300, BufferedImage.TYPE_INT_RGB);
				Graphics2D graphics = image.createGraphics();
				try
				{
					for (Overlay overlay : overlays)
					{
						overlay.render(graphics);
					}
				}
				finally
				{
					graphics.dispose();
				}
				int countY = firstRow(image, Color.RED.getRGB());
				int actionY = firstRow(image, Color.GREEN.getRGB());
				assertTrue("Both tooltips must render in this frame", countY >= 0 && actionY >= 0);
				boolean above = anchor == ImprovedMenusConfig.CountAnchor.ABOVE_LEFT
						|| anchor == ImprovedMenusConfig.CountAnchor.ABOVE_RIGHT;
				assertEquals(anchor.toString(), above, countY < actionY);
				assertTrue("No stale tooltip in the next frame", manager.getTooltips().isEmpty());
			}
		}
		}
	}

	private static int firstRow(BufferedImage image, int color)
	{
		for (int y = 0; y < image.getHeight(); y++)
			for (int x = 0; x < image.getWidth(); x++)
				if (image.getRGB(x, y) == color)
				{
					return y;
				}
		return -1;
	}
}

package com.improvedmenus;

