				entry(MenuAction.GAME_OBJECT_FIRST_OPTION), entry(MenuAction.EXAMINE_OBJECT),
				entry(MenuAction.GROUND_ITEM_THIRD_OPTION), entry(MenuAction.CC_OP), entry(MenuAction.WALK) };
