	@Test
	public void rightAnchorReservesStackWidthAndClampsToCanvas()
	{
		Client client = mock(Client.class);
		when(client.getCanvasWidth()).thenReturn(400);
		when(client.getCanvasHeight()).thenReturn(100);
		TooltipManager manager = new TooltipManager();
		manager.add(new Tooltip("A much wider target action tooltip"));
		OptionCountTooltip row = new OptionCountTooltip("+2 options", manager, client, Color.BLACK);
		manager.add(new Tooltip(row));
		BufferedImage image = new BufferedImage(400, 100, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		row.setPreferredLocation(new Point(10, 20));
		Dimension size = row.render(graphics);
