			}
		});
		ImprovedMenusPlugin plugin = injector.getInstance(ImprovedMenusPlugin.class);
		for (int i = 0; i < 2; i++)
		{
			SwingUtilities.invokeAndWait(() ->
			{
				plugin.startUp();
				bus.register(plugin);
			});
			SwingUtilities.invokeAndWait(() ->
			{
			});
			bus.post(new net.runelite.api.events.BeforeMenuRender());
			SwingUtilities.invokeAndWait(() ->
			{
				bus.unregister(plugin);
				plugin.shutDown();
			});
			SwingUtilities.invokeAndWait(() ->
			{
			});
		}
		verify(mouse, times(2)).registerMouseListener(any());
		verify(mouse, times(2)).unregisterMouseListener(any());
		verify(bus, times(2)).register(any(ButtonGuard.class));
		verify(bus, times(2)).unregister(any(ButtonGuard.class));
