		SwingUtilities.invokeAndWait(() ->
		{
		});
		verify(toolbar, times(3)).addNavigation(any(NavigationButton.class));
		when(config.hideSidePanel()).thenReturn(true);
		plugin.onConfigChanged(changed);
		SwingUtilities.invokeAndWait(() ->
