public class PresentationTest
{
	@Test
	public void additionalOptionsExcludeWalkCancelAndLocalControls()
	{
		assertEquals(1,
				MenuPresentation
						.additionalCount(new MenuEntry[] { TestMenus.entry("Cancel", "", MenuAction.CANCEL, -1, 0),
								TestMenus.entry("Walk here", "", MenuAction.WALK, -1, 0),
								TestMenus.entry("Colors", "", MenuAction.RUNELITE, -1, 0),
								TestMenus.entry("Take", "Coins", MenuAction.GROUND_ITEM_THIRD_OPTION, -1, 0),
								TestMenus.entry("Examine", "Coins", MenuAction.EXAMINE_ITEM_GROUND, -1, 0) }));
	}

	@Test
	public void countNeverNegative()
	{
		assertEquals(0, MenuPresentation.additionalCount(new MenuEntry[0]));
	}

	@Test
	public void examineSwitchRecognizesNpcObjectGroundAndInventoryExamines()
	{
		MenuEntry action = TestMenus.entry("Talk-to", "NPC", MenuAction.NPC_FIRST_OPTION, -1, 0);
		MenuEntry[] entries = { action, TestMenus.entry("Examine", "NPC", MenuAction.EXAMINE_NPC, -1, 0),
				TestMenus.entry("Examine", "Tree", MenuAction.EXAMINE_OBJECT, -1, 0),
				TestMenus.entry("Examine", "Coins", MenuAction.EXAMINE_ITEM_GROUND, -1, 0),
