	private Menu hoveredMenu(MenuEntry... entries)
	{
		Menu menu = TestMenus.menu(entries);
		when(menu.getMenuX()).thenReturn(100);
		when(menu.getMenuY()).thenReturn(200);
		when(menu.getMenuWidth()).thenReturn(200);
		when(menu.getMenuHeight()).thenReturn(100);
		when(config.enableColors()).thenReturn(true);
		when(config.yellowHover()).thenReturn(true);
		when(client.getMouseCanvasPosition()).thenReturn(new Point(120, 231));
		return menu;
	}

	@Test
	public void hoverReleasesOnlyOwnedColorThenRestoresItOnLeave()
	{
		MenuEntry entry = TestMenus.entry("<img=2><col=00ff00>Use</col>", "<col=ff9040>Sword</col>", MenuAction.CC_OP,
				1, InterfaceID.INVENTORY);
		Menu menu = hoveredMenu(entry);
		engine.applyOpened(menu);
		String colored = entry.getOption();
		engine.highlightHovered(menu);
		assertEquals("<img=2>Use", entry.getOption());
		assertEquals("<col=ff9040>Sword</col>", entry.getTarget());
		when(client.getMouseCanvasPosition()).thenReturn(new Point(90, 231));
		engine.highlightHovered(menu);
		assertEquals(colored, entry.getOption());
		when(client.getMouseCanvasPosition()).thenReturn(new Point(120, 231));
		engine.highlightHovered(menu);
		engine.clear();
		assertEquals("<img=2><col=00ff00>Use</col>", entry.getOption());
	}

	@Test
	public void hoverToggleAndOtherPluginChangesAreRespected()
	{
		MenuEntry entry = TestMenus.entry("Use", "Sword", MenuAction.CC_OP, 1, InterfaceID.INVENTORY);
		Menu menu = hoveredMenu(entry);
		engine.applyOpened(menu);
		String colored = entry.getOption();
		engine.highlightHovered(menu);
		when(config.yellowHover()).thenReturn(false);
		engine.highlightHovered(menu);
		assertEquals(colored, entry.getOption());
		entry.setOption("<col=0000ff>Use</col>");
		when(config.yellowHover()).thenReturn(true);
		engine.highlightHovered(menu);
		assertEquals("<col=0000ff>Use</col>", entry.getOption());
		engine.clear();
		assertEquals("<col=0000ff>Use</col>", entry.getOption());
	}

	@Test
	public void hoverHandlesRootScrollingAndDoesNotHighlightHeader()
	{
		MenuEntry lower = TestMenus.entry("Use", "Sword", MenuAction.CC_OP, 1, InterfaceID.INVENTORY);
		MenuEntry upper = TestMenus.entry("Use", "Sword", MenuAction.CC_OP, 2, InterfaceID.INVENTORY);
		Menu menu = hoveredMenu(lower, upper);
		when(client.isMenuScrollable()).thenReturn(true);
		when(client.getMenuScroll()).thenReturn(1);
		engine.applyOpened(menu);
		engine.highlightHovered(menu);
		assertEquals("Use", lower.getOption());
		assertTrue(upper.getOption().contains("ff0000"));
		when(client.getMouseCanvasPosition()).thenReturn(new Point(120, 211));
		engine.highlightHovered(menu);
		assertTrue(lower.getOption().contains("ff0000"));
	}

	@Test
	public void staleSubmenuBoundsCannotStealRootHover()
	{
		MenuEntry child = TestMenus.entry("Use", "Sword", MenuAction.CC_OP, 1, InterfaceID.INVENTORY);
		Menu submenu = hoveredMenu(child);
		MenuEntry parent = TestMenus.entry("Use", "Sword", MenuAction.CC_OP, 2, InterfaceID.INVENTORY);
		when(parent.getSubMenu()).thenReturn(submenu);
		Menu menu = hoveredMenu(parent);
		engine.applyOpened(menu);
		String childColor = child.getOption();
		engine.highlightHovered(menu);
		assertEquals("Use", parent.getOption());
		assertEquals(childColor, child.getOption());
		verify(submenu, never()).getMenuX();
		verify(submenu, never()).getMenuWidth();
		verify(child, never()).onClick(any());
		verify(child, never()).setType(any());
		when(client.getMouseCanvasPosition()).thenReturn(new Point(90, 231));
		engine.highlightHovered(menu);
		assertTrue(parent.getOption().contains("ff0000"));
		engine.clear();
		assertEquals("Use", parent.getOption());
		assertEquals("Use", child.getOption());
	}

	@Test
	public void submenuOutsideRootKeepsItsColorWithoutReadingStaleBounds()
	{
		MenuEntry child = TestMenus.entry("Use", "Sword", MenuAction.CC_OP, 1, InterfaceID.INVENTORY);
		Menu submenu = hoveredMenu(child);
		when(submenu.getMenuX()).thenReturn(350);
		MenuEntry parent = TestMenus.entry("Actions", "Sword", MenuAction.CC_OP, 2, InterfaceID.INVENTORY);
		when(parent.getSubMenu()).thenReturn(submenu);
		Menu menu = hoveredMenu(parent);
		when(client.getMouseCanvasPosition()).thenReturn(new Point(370, 231));
		engine.applyOpened(menu);
		String colored = child.getOption();
		engine.highlightHovered(menu);
		assertEquals(colored, child.getOption());
		verify(submenu, never()).getMenuX();
		engine.reload();
		assertEquals("Use", child.getOption());
	}
}

package com.improvedmenus;

import org.junit.Test;
import static org.junit.Assert.*;

public class SavedColourExportTest
{
	@Test
	public void exportsOnlyEquivalentActionRules()
	{
		SavedColourExport export = new SavedColourExport("*:Take:#ff0000;*:Talk-to:#00ff00;Goblin:Attack:#112233;*:Chop*:#334455");
		assertEquals("Take=#ff0000\nTalk-to=#00ff00", export.rules);
		assertEquals("Goblin:Attack:#112233\n*:Chop*:#334455", export.retained);
	}

	@Test
	public void doesNotBroadenOverlappingOrTargetSpecificRules()
	{
		SavedColourExport export = new SavedColourExport("Goblin:Attack:#ff0000;*:Attack:#00ff00;*:T*:#ff0000;*:Take:#00ff00");
		assertEquals("", export.rules);
		assertEquals(4, export.retained.split("\n").length);
	}

	@Test
	public void deduplicatesIdenticalRulesAndRejectsStylerSeparators()
	{
		SavedColourExport export = new SavedColourExport("*:Take:#ff0000;*:take:#ff0000;*:A=B:#00ff00");
		assertEquals("Take=#ff0000", export.rules);
		assertEquals("*:A=B:#00ff00", export.retained);
	}

	@Test
	public void reportsRulesBeyondStylerLimits()
	{
		StringBuilder rules = new StringBuilder();
		for (int i = 0; i < 51; i++)
			rules.append("*:Action").append(i).append(":#ff0000;");
		rules.append("*:").append("A".repeat(65)).append(":#ffffff");
		SavedColourExport export = new SavedColourExport(rules.toString());
		assertEquals(50, export.rules.split("\n").length);
		assertEquals(2, export.retained.split("\n").length);
	}
}

package com.improvedmenus;

import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.*;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.menuentryswapper.MenuEntrySwapperConfig;
import net.runelite.client.plugins.menuentryswapper.MenuEntrySwapperPlugin;
import org.junit.Before;
import org.junit.Test;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class SwapperConfigurationCompatibilityTest
{
	@Mock
	private Client client;
	@Mock
	private ItemManager items;
	@Mock
	private ConfigManager configs;
	@Mock
	private MenuEntrySwapperConfig swapperConfig;
	@InjectMocks
	private MenuEntrySwapperPlugin swapper;
	private ImprovedMenusConfig config;
	private MenuEngine engine;

	@Before
	public void setup()
	{
		MockitoAnnotations.openMocks(this);
		config = mock(ImprovedMenusConfig.class, CALLS_REAL_METHODS);
		when(config.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.NONE);
		when(config.enableColors()).thenReturn(true);
		when(config.colors()).thenReturn("*:*:#123abc");
		when(config.examineInventory()).thenReturn(true);
		when(config.examineObject()).thenReturn(true);
		when(config.examineNpc()).thenReturn(true);
		when(config.keepLoneObject()).thenReturn(false);
		when(config.keepLoneNpc()).thenReturn(false);
		when(client.isKeyPressed(KeyCode.KC_SHIFT)).thenReturn(true);
		engine = Guice.createInjector(new AbstractModule()
		{
			@Override
			protected void configure()
			{
				bind(Client.class).toInstance(client);
				bind(ImprovedMenusConfig.class).toInstance(config);
				bind(ItemManager.class).toInstance(items);
			}
		}).getInstance(MenuEngine.class);
		engine.reload();
	}

	private MenuEntry examine(MenuAction type, int group)
	{
		MenuEntry entry = TestMenus.entry("Examine", "Rune sword", type, 100, group);
		when(entry.getIdentifier()).thenReturn(10);
		return entry;
	}

	@Test
	public void shiftedExamineSurvivesUntilOpenThenNormalCleanupResumes()
	{
		for (MenuEntry anchor : new MenuEntry[] { examine(MenuAction.EXAMINE_OBJECT, 0),
				examine(MenuAction.EXAMINE_NPC, 0), examine(MenuAction.CC_OP, InterfaceID.INVENTORY),
				examine(MenuAction.CC_OP_LOW_PRIORITY, InterfaceID.WORNITEMS) })
		{
			Menu menu = TestMenus.menu(anchor);
			engine.apply(menu);
			assertArrayEquals(new MenuEntry[] { anchor }, menu.getMenuEntries());
			assertEquals("Examine", anchor.getOption());
			engine.applyOpened(menu);

			assertEquals(0, menu.getMenuEntries().length);
		}
	}

	@Test
	public void holdingShiftRestoresPreviouslyColoredAnchor()
	{
		when(config.examineInventory()).thenReturn(false);
		when(client.isKeyPressed(KeyCode.KC_SHIFT)).thenReturn(false);
		MenuEntry anchor = examine(MenuAction.CC_OP, InterfaceID.INVENTORY);
		Menu menu = TestMenus.menu(anchor);
		engine.apply(menu);
		assertNotEquals("Examine", anchor.getOption());
		when(client.isKeyPressed(KeyCode.KC_SHIFT)).thenReturn(true);
		engine.apply(menu);
		assertEquals("Examine", anchor.getOption());
	}

	@Test
	public void ordinaryMenusAndOtherProtectionsStillFilter()
	{
		when(client.isKeyPressed(KeyCode.KC_SHIFT)).thenReturn(false);
		Menu menu = TestMenus.menu(examine(MenuAction.CC_OP, InterfaceID.INVENTORY));
		engine.apply(menu);
		assertEquals(0, menu.getMenuEntries().length);
		when(client.isKeyPressed(KeyCode.KC_SHIFT)).thenReturn(true);
		when(config.potionEmpty()).thenReturn(true);
		menu = TestMenus
				.menu(TestMenus.entry("Empty", "Prayer potion(4)", MenuAction.CC_OP, 100, InterfaceID.INVENTORY));
		engine.apply(menu);
		assertEquals(0, menu.getMenuEntries().length);
	}

	@Test
	public void realSwapperBuildsControlsBeforeWorkshopHidesExamine()
	{
		when(swapperConfig.leftClickCustomization()).thenReturn(true);
		when(swapperConfig.shiftClickCustomization()).thenReturn(true);
		MenuEntry anchor = examine(MenuAction.CC_OP, InterfaceID.INVENTORY);
		Widget widget = mock(Widget.class);
		when(widget.getId()).thenReturn(InterfaceID.INVENTORY << 16);
		when(anchor.getWidget()).thenReturn(widget);
		ItemComposition item = mock(ItemComposition.class);
		when(item.getId()).thenReturn(100);
		when(item.getInventoryActions()).thenReturn(new String[] { "Wield", null, null, null, "Drop" });
		when(items.getItemComposition(100)).thenReturn(item);
		List<MenuEntry> created = new ArrayList<>();
		Menu menu = TestMenus.menu(anchor);
		when(client.createMenuEntry(anyInt())).thenAnswer(i ->
		{
			MenuEntry entry = TestMenus.entry("", "", MenuAction.RUNELITE, -1, 0);
			Menu sub = mock(Menu.class);
			when(entry.createSubMenu()).thenReturn(sub);
			when(entry.getSubMenu()).thenReturn(sub);
			when(sub.getMenuEntries()).thenReturn(new MenuEntry[0]);
			when(sub.createMenuEntry(anyInt())).thenAnswer(j -> TestMenus.entry("", "", MenuAction.RUNELITE, -1, 0));
			created.add(entry);
			List<MenuEntry> entries = new ArrayList<>(Arrays.asList(menu.getMenuEntries()));
			entries.add(0, entry);
			menu.setMenuEntries(entries.toArray(new MenuEntry[0]));
			return entry;
		});
		engine.apply(menu);
		MenuOpened event = new MenuOpened();
		event.setMenuEntries(menu.getMenuEntries());
		swapper.onMenuOpened(event);
		assertEquals(2, created.size());
		assertEquals("Swap left-click", created.get(0).getOption());
		assertEquals("Swap shift-click", created.get(1).getOption());
		for (MenuEntry entry : created)
		{
			clearInvocations(entry);
		}
		engine.applyOpened(menu);
		assertEquals(2, menu.getMenuEntries().length);
		assertTrue(Arrays.asList(menu.getMenuEntries()).containsAll(created));
		for (MenuEntry entry : created)
		{
			verify(entry, never()).setType(any());
		}
	}
}

