		Menu menu = TestMenus.menu(heading, walk);
		engine.apply(menu);
		assertEquals(2, menu.getMenuEntries().length);
		engine.applyOpened(menu);
		assertArrayEquals(new MenuEntry[] { walk }, menu.getMenuEntries());
