public class UpstreamMenuCompatibilityTest
{
	private MenuEngine engine()
	{
		Client c = mock(Client.class);
		ImprovedMenusConfig cfg = mock(ImprovedMenusConfig.class, CALLS_REAL_METHODS);
		when(cfg.revealKey()).thenReturn(ImprovedMenusConfig.RevealKey.NONE);
		when(cfg.enableColors()).thenReturn(true);
		when(cfg.colors()).thenReturn("*:*:#123abc");
		when(cfg.examineObject()).thenReturn(true);
		when(cfg.keepLoneObject()).thenReturn(false);
		when(cfg.hideCancel()).thenReturn(true);
		MenuEngine e = Guice.createInjector(new AbstractModule()
		{
			protected void configure()
			{
				bind(Client.class).toInstance(c);
				bind(ImprovedMenusConfig.class).toInstance(cfg);
				bind(ItemManager.class).toInstance(mock(ItemManager.class));
			}
		}).getInstance(MenuEngine.class);
		e.reload();
		return e;
