	@Test
	public void recoloringRetainsCustomCallbacksAndAllActionMetadata()
	{
		MenuEngine e = engine();
		for (String name : new String[] { "Lookup", "Equipment", "Predict", "Inspect" })
		{
			MenuEntry entry = TestMenus.entry(name, "Alice", MenuAction.RUNELITE, -1, 0);
			Consumer<MenuEntry> cb = mock(Consumer.class);
			when(entry.onClick()).thenReturn(cb);
			Menu menu = TestMenus.menu(entry);
			e.apply(menu);
			assertSame(entry, menu.getMenuEntries()[0]);
			assertSame(cb, entry.onClick());
			entry.onClick().accept(entry);
			verify(cb).accept(entry);
			verify(entry, never()).setType(any());
			verify(entry, never()).setIdentifier(anyInt());
			verify(entry, never()).setParam0(anyInt());
			verify(entry, never()).setParam1(anyInt());
			e.clear();
			assertEquals(name, entry.getOption());
		}
	}

	@Test
	public void colorsPreserveSwappedCapeAndBankOrdering()
	{
		MenuEngine e = engine();
		for (int group : new int[] { InterfaceID.INVENTORY, InterfaceID.BANKMAIN })
		{
			MenuEntry cancel = TestMenus.entry("Cancel", "", MenuAction.CANCEL, -1, 0),
					shift = TestMenus.entry("Crafting Guild", "Max cape", MenuAction.CC_OP, 100, group),
					left = TestMenus.entry("Home Teleport", "Max cape", MenuAction.CC_OP, 100, group);
			MenuEntry[] swapped = { cancel, shift, left };
			Menu menu = TestMenus.menu(swapped);
			e.apply(menu);
			assertArrayEquals(swapped, menu.getMenuEntries());
			assertEquals("Home Teleport", MenuRules.plain(menu.getMenuEntries()[2].getOption()));
			e.clear();
			assertEquals("Home Teleport", left.getOption());
		}
	}

