	public void submenuLocationsKeepColorAndCallback()
	{
		MenuEngine e = engine();
		MenuEntry parent = TestMenus.entry("Teleport", "Achievement cape", MenuAction.RUNELITE, -1, 0),
				child = TestMenus.entry("Jalsavrah", "", MenuAction.RUNELITE, -1, 0);
