		when(child.onClick()).thenReturn(cb);
		Menu sub = TestMenus.menu(child);
		when(parent.getSubMenu()).thenReturn(sub);
		e.apply(TestMenus.menu(parent));
		assertEquals("<col=123abc>Jalsavrah</col>", child.getOption());
		assertSame(cb, child.onClick());
	}

	@Test
	public void sailsExamineRemovedBeforeOpeningAndCancelFallbackSurvives()
	{
		MenuEngine e = engine();
		MenuEntry sails = TestMenus.entry("Examine sails", "Sails", MenuAction.EXAMINE_OBJECT, -1, 0),
				cancel = TestMenus.entry("Cancel", "", MenuAction.CANCEL, -1, 0);
