		when(icons.chatIconIndex(2)).thenReturn(4);
		MenuPresentation p = Guice.createInjector(new AbstractModule()
		{
			protected void configure()
			{
				bind(LootFiltersCompatibility.class).toInstance(mock(LootFiltersCompatibility.class));
				bind(java.util.concurrent.ScheduledExecutorService.class)
						.toInstance(mock(java.util.concurrent.ScheduledExecutorService.class));
				bind(net.runelite.client.config.RuneLiteConfig.class)
						.toInstance(mock(net.runelite.client.config.RuneLiteConfig.class));
				bind(Client.class).toInstance(client);
				bind(ImprovedMenusConfig.class).toInstance(config);
				bind(ChatIconManager.class).toInstance(icons);
				bind(ItemManager.class).toInstance(mock(ItemManager.class));
				bind(TooltipManager.class).toInstance(mock(TooltipManager.class));
			}
		}).getInstance(MenuPresentation.class);
		p.start();
		MenuEntry entry = e("Take", "Coins", MenuAction.GROUND_ITEM_THIRD_OPTION, 1, 0);
		p.decorate(menu(entry));
		entry.setTarget("<col=ff0000>Coins</col>");
		p.stop();
		assertEquals("<col=ff0000>Coins</col>", entry.getTarget());
		entry = e("Take", "Coins", MenuAction.GROUND_ITEM_THIRD_OPTION, 1, 0);
		p.decorate(menu(entry));
		entry.setIdentifier(2);
		p.stop();
		assertEquals("<img=4>Coins", entry.getTarget());
		MenuEntry root = e("Take", "Coins", MenuAction.GROUND_ITEM_THIRD_OPTION, 1, 0);
		p.decorate(menu(root));
		when(config.groundIcons()).thenReturn(false);
		p.decorate(menu(root));
		assertEquals("Coins", root.getTarget());
	}
